-- F7: private OCR, verified text, literal sources and reviewed assistance.
-- No approved legal knowledge, AI policy, provider connection or OCR enablement is seeded.
create table public.legal_assistance_settings(tenant_id uuid primary key references public.tenants(id),ocr_enabled boolean not null default false,ocr_monthly_page_limit integer not null default 1000 check(ocr_monthly_page_limit between 1 and 100000),ocr_max_pages integer not null default 20 check(ocr_max_pages between 1 and 20),updated_by uuid references public.profiles(id),updated_at timestamptz not null default clock_timestamp());
create table public.legal_assistance_audit(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),case_id uuid,category text not null check(category in ('general','medical','fiscal','restricted')),event_type text not null,actor_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default clock_timestamp(),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id));
create table public.legal_ocr_jobs(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,category text not null check(category in ('general','medical','fiscal')),document_id uuid not null,source_sha256 text not null,idempotency_key uuid not null,state text not null check(state in ('queued','running','succeeded','partial','failed','cancelled','authorization_revoked','unknown')),attempts integer not null default 0 check(attempts between 0 and 1),max_pages integer not null check(max_pages between 1 and 20),quota_pages integer not null check(quota_pages between 0 and 20),quota_month date not null,pages_total integer,processed_pages integer not null default 0,kernel_version text,error_code text,result_version_id uuid,base_version_id uuid,lease_token uuid,lease_until timestamptz,result_sha256 text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),started_at timestamptz,finished_at timestamptz,updated_at timestamptz not null default clock_timestamp(),unique(tenant_id,idempotency_key),unique(id,case_id,tenant_id),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id),foreign key(document_id,case_id,tenant_id) references public.legal_case_documents(id,case_id,tenant_id));
create unique index legal_ocr_one_live on public.legal_ocr_jobs(document_id,source_sha256) where state in ('queued','running');
create index legal_ocr_queue on public.legal_ocr_jobs(created_at,id) where state in ('queued','running');
create index legal_ocr_month on public.legal_ocr_jobs(tenant_id,quota_month);
create table public.legal_document_text_versions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,category text not null check(category in ('general','medical','fiscal')),document_id uuid not null,source_sha256 text not null,version_number integer not null check(version_number>0),mode text not null check(mode in ('ocr','manual','correction')),previous_version_id uuid,ocr_job_id uuid,pages_total integer check(pages_total between 1 and 1000),completeness text not null check(completeness in ('complete','partial','unknown')),engine jsonb not null default '{}',state text not null default 'draft' check(state in ('draft','in_review','approved','returned','revoked')),note text not null default '' check(length(note)<=4000),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text not null default '',unique(id,case_id,tenant_id),unique(document_id,version_number),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id),foreign key(document_id,case_id,tenant_id) references public.legal_case_documents(id,case_id,tenant_id),foreign key(previous_version_id,case_id,tenant_id) references public.legal_document_text_versions(id,case_id,tenant_id),foreign key(ocr_job_id,case_id,tenant_id) references public.legal_ocr_jobs(id,case_id,tenant_id));
alter table public.legal_ocr_jobs add foreign key(result_version_id,case_id,tenant_id) references public.legal_document_text_versions(id,case_id,tenant_id),add foreign key(base_version_id,case_id,tenant_id) references public.legal_document_text_versions(id,case_id,tenant_id);
create table public.legal_document_text_pages(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,version_id uuid not null,category text not null,page_number integer not null check(page_number between 1 and 1000),text text,page_status text not null check(page_status in ('recognized','low_confidence','no_text_recognized','not_processed','manual')),words jsonb not null default '[]',confidence_mean text,width integer,height integer,coordinate_system text not null default 'rendered_pixels',review_state text not null default 'unreviewed' check(review_state in ('unreviewed','approved','returned')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text not null default '',unique(version_id,page_number),foreign key(version_id,case_id,tenant_id) references public.legal_document_text_versions(id,case_id,tenant_id));
create table public.legal_document_text_reviews(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,version_id uuid not null,page_number integer not null,decision text not null check(decision in ('approved','returned')),note text not null,reviewed_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),foreign key(version_id,page_number) references public.legal_document_text_pages(version_id,page_number),foreign key(version_id,case_id,tenant_id) references public.legal_document_text_versions(id,case_id,tenant_id));
create table public.legal_knowledge_versions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),knowledge_key text not null check(length(btrim(knowledge_key)) between 1 and 80),version_number integer not null check(version_number>0),title text not null check(length(btrim(title)) between 1 and 200),kind text not null check(kind in ('template','jurisprudence','note')),source_url text not null default '' check(length(source_url)<=2000),source_document_id uuid references public.legal_case_documents(id),source_document_sha256 text,checked_on date,version_note text not null check(length(btrim(version_note)) between 1 and 4000),scope text not null check(length(btrim(scope)) between 1 and 4000),text text not null check(length(text) between 1 and 200000),source_sha256 text not null,state text not null default 'draft' check(state in ('draft','approved','rejected','revoked')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text not null default '',unique(tenant_id,knowledge_key,version_number),unique(id,tenant_id),check(isfinite(checked_on)));
create table public.legal_source_citations(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,category text not null check(category in ('general','medical','fiscal','restricted')),source_kind text not null check(source_kind in ('text_page','knowledge')),source_version_id uuid not null,document_id uuid,page_number integer,start_offset integer not null check(start_offset>0),quote text not null check(length(quote) between 1 and 3000),source_sha256 text not null,source_label text not null check(length(source_label) between 1 and 200),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id));
create table public.legal_assistance_draft_versions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,category text not null check(category in ('general','medical','fiscal','restricted')),draft_key text not null check(length(btrim(draft_key)) between 1 and 80),version_number integer not null check(version_number>0),kind text not null check(kind in ('summary','chronology','message','pleading')),purpose text not null check(length(btrim(purpose)) between 1 and 2000),body jsonb not null,citation_ids uuid[] not null default '{}',snapshot jsonb not null,snapshot_hash text not null,mode text not null check(mode in ('manual','ai')),ai_job_id uuid,previous_version_id uuid,state text not null default 'draft' check(state in ('draft','in_review','reviewed','returned','revoked')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text not null default '',unique(case_id,draft_key,version_number),unique(id,case_id,tenant_id),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id),foreign key(previous_version_id,case_id,tenant_id) references public.legal_assistance_draft_versions(id,case_id,tenant_id));
create table public.legal_assistance_draft_reviews(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,version_id uuid not null,decision text not null,note text not null,reviewed_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),foreign key(version_id,case_id,tenant_id) references public.legal_assistance_draft_versions(id,case_id,tenant_id));
create table public.legal_assistance_transfers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,version_id uuid not null,target_kind text not null check(target_kind in ('instrument','publication')),target_id uuid not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),unique(target_kind,target_id),foreign key(version_id,case_id,tenant_id) references public.legal_assistance_draft_versions(id,case_id,tenant_id));
create table public.legal_ai_policy_versions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),policy_key text not null check(length(btrim(policy_key)) between 1 and 80),version_number integer not null,title text not null check(length(btrim(title)) between 1 and 200),model text not null check(model ~ '^[a-zA-Z0-9._:-]{1,150}$'),purpose_note text not null check(length(btrim(purpose_note)) between 1 and 4000),retention_note text not null check(length(btrim(retention_note)) between 1 and 4000),source_document_id uuid references public.legal_case_documents(id),source_document_sha256 text,source_url text not null check(length(source_url)<=2000),checked_on date,valid_from date,valid_until date,allow_medical boolean not null default false,allow_fiscal boolean not null default false,currency text not null check(currency='USD'),rate_unit text not null check(rate_unit='per_million_tokens'),input_rate numeric(18,8) not null check(input_rate>0 and input_rate<1000000),output_rate numeric(18,8) not null check(output_rate>0 and output_rate<1000000),monthly_budget numeric(18,6) not null check(monthly_budget>0 and monthly_budget<1000000000),max_input_tokens integer not null check(max_input_tokens between 256 and 50000),max_output_tokens integer not null check(max_output_tokens between 256 and 4000),state text not null default 'draft' check(state in ('draft','approved','rejected','revoked')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text not null default '',unique(tenant_id,policy_key,version_number),unique(id,tenant_id),check(isfinite(checked_on) and isfinite(valid_from) and isfinite(valid_until)),check(valid_until>=valid_from));
create table public.legal_ai_connections(id uuid primary key default gen_random_uuid(),tenant_id uuid not null unique references public.tenants(id),account_id text not null unique check(account_id ~ '^[a-zA-Z0-9_-]{1,100}$'),model text not null,policy_version_id uuid not null,enabled boolean not null default false,state text not null check(state in ('not_configured','enabled','disabled','policy_required')),created_by uuid not null references public.profiles(id),updated_at timestamptz not null default clock_timestamp(),foreign key(policy_version_id,tenant_id) references public.legal_ai_policy_versions(id,tenant_id));
create table public.legal_ai_jobs(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid not null,category text not null check(category in ('general','medical','fiscal','restricted')),draft_key text not null,kind text not null check(kind in ('summary','chronology','message','pleading')),purpose text not null,citation_ids uuid[] not null,idempotency_key uuid not null,max_output_tokens integer not null check(max_output_tokens between 256 and 4000),connection_id uuid references public.legal_ai_connections(id),policy_version_id uuid,snapshot jsonb not null,snapshot_hash text not null,previous_version_id uuid,state text not null check(state in ('queued','running','succeeded','failed','cancelled','authorization_revoked','not_configured','quota_exhausted','unknown')),input_token_bound integer,input_tokens integer,output_tokens integer,reserved_cost numeric(18,6) not null default 0,measured_cost numeric(18,6),quota_cost numeric(18,6) not null default 0,quota_month date not null,consumption text not null default 'not_sent' check(consumption in ('not_sent','reserved','reported','uncertain')),result_version_id uuid,error_code text,lease_token uuid,lease_until timestamptz,response_id text,payload_hash text not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),started_at timestamptz,finished_at timestamptz,unique(tenant_id,idempotency_key),unique(id,case_id,tenant_id),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id),foreign key(policy_version_id,tenant_id) references public.legal_ai_policy_versions(id,tenant_id),foreign key(result_version_id,case_id,tenant_id) references public.legal_assistance_draft_versions(id,case_id,tenant_id),foreign key(previous_version_id,case_id,tenant_id) references public.legal_assistance_draft_versions(id,case_id,tenant_id));
alter table public.legal_assistance_draft_versions add foreign key(ai_job_id,case_id,tenant_id) references public.legal_ai_jobs(id,case_id,tenant_id);
create index legal_ai_queue on public.legal_ai_jobs(created_at,id) where state in ('queued','not_configured','running');
create index legal_ai_month on public.legal_ai_jobs(tenant_id,quota_month);

create or replace function public._legal_assistance_actor(p_case_id uuid,p_actor_id uuid,p_category text,p_edit boolean default false,p_owner boolean default false) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
 select exists(select 1 from public.legal_cases c join public.profiles p on p.id=p_actor_id and p.tenant_id=c.tenant_id and p.status='active' join public.legal_workspace_features w on w.tenant_id=c.tenant_id and w.enabled left join public.legal_case_members m on m.case_id=c.id and m.profile_id=p.id where c.id=p_case_id and p_category in ('general','medical','fiscal','restricted') and (c.owner_id=p.id or (not p_owner and m.profile_id is not null and (not p_edit or m.can_edit) and (p_category='general' or p_category='medical' and m.can_view_medical or p_category='fiscal' and m.can_view_fiscal or p_category='restricted' and m.can_view_medical and m.can_view_fiscal))));
$$;
create or replace function public._legal_assistance_document(p_document_id uuid,p_actor_id uuid,p_edit boolean default false) returns public.legal_case_documents language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.legal_case_documents;begin
 select * into d from public.legal_case_documents where id=p_document_id;if not found or d.status<>'ready' or d.sha256 is null or not public._legal_assistance_actor(d.case_id,p_actor_id,d.category,p_edit) then raise exception 'Current authorized ready source required' using errcode='42501';end if;return d;
end;$$;
create or replace function public._legal_assistance_event(p_tenant uuid,p_case uuid,p_category text,p_type text,p_ids jsonb default '{}',p_actor uuid default auth.uid()) returns void language sql security definer set search_path=pg_catalog,public,pg_temp as $$insert into public.legal_assistance_audit(tenant_id,case_id,category,event_type,metadata,actor_id) values(p_tenant,p_case,p_category,p_type,p_ids,p_actor);$$;
create or replace function public._legal_assistance_month() returns date language sql stable set search_path=pg_catalog,public,pg_temp as $$select date_trunc('month',clock_timestamp() at time zone 'America/Sao_Paulo')::date;$$;
create or replace function public._legal_assistance_projection(p_row jsonb,p_kind text) returns jsonb language plpgsql immutable set search_path=pg_catalog,public,pg_temp as $$declare r jsonb:=p_row;begin
 if r is null then return null;end if;r:=r-array['lease_token','lease_until','payload_hash','result_sha256','snapshot','snapshot_hash','text','words','body','purpose','citation_ids','source_document_sha256'];
 if p_kind='text_page' then r:=r-'review_note';end if;if p_kind='ai_connection' then r:=r-'account_id';end if;
 if p_kind='ai_policy' then r:=r||jsonb_build_object('input_rate',p_row->>'input_rate','output_rate',p_row->>'output_rate','monthly_budget',p_row->>'monthly_budget');end if;
 if p_kind='ai_job' then r:=r||jsonb_build_object('reserved_cost',p_row->>'reserved_cost','measured_cost',p_row->>'measured_cost','quota_cost',p_row->>'quota_cost');end if;return r;
end;$$;
create or replace function public._legal_assistance_text_current(p_version_id uuid,p_actor_id uuid,p_approved_page integer default null) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
 select exists(select 1 from public.legal_document_text_versions v join public.legal_case_documents d on d.id=v.document_id and d.case_id=v.case_id and d.tenant_id=v.tenant_id and d.category=v.category and d.status='ready' and d.sha256=v.source_sha256 where v.id=p_version_id and v.state<>'revoked' and public._legal_assistance_actor(v.case_id,p_actor_id,v.category) and not exists(select 1 from public.legal_document_text_versions newer where newer.document_id=v.document_id and newer.version_number>v.version_number) and (p_approved_page is null or exists(select 1 from public.legal_document_text_pages p where p.version_id=v.id and p.page_number=p_approved_page and p.review_state='approved' and p.page_status<>'not_processed' and public._legal_assistance_actor(v.case_id,p.reviewed_by,v.category,false,true))));
$$;
create or replace function public._legal_assistance_knowledge_access(p_version uuid,p_actor uuid,p_current boolean default false) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
 select exists(select 1 from public.legal_knowledge_versions v join public.profiles a on a.id=p_actor and a.tenant_id=v.tenant_id and a.status='active' join public.legal_workspace_features w on w.tenant_id=v.tenant_id and w.enabled where v.id=p_version and v.state<>'revoked' and (not p_current or (v.state='approved' and exists(select 1 from public.profiles reviewer where reviewer.id=v.reviewed_by and reviewer.tenant_id=v.tenant_id and reviewer.role='admin' and reviewer.status='active') and not exists(select 1 from public.legal_knowledge_versions n where n.tenant_id=v.tenant_id and n.knowledge_key=v.knowledge_key and n.version_number>v.version_number))) and (v.source_document_id is null or exists(select 1 from public.legal_case_documents d where d.id=v.source_document_id and d.tenant_id=v.tenant_id and d.category='general' and d.status='ready' and d.sha256=v.source_document_sha256 and public._legal_assistance_actor(d.case_id,p_actor,'general') and (not p_current or public._legal_assistance_actor(d.case_id,v.reviewed_by,'general')))));
$$;
create or replace function public._legal_assistance_citation_valid(p_id uuid,p_actor uuid) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_source_citations;v public.legal_document_text_versions;p public.legal_document_text_pages;k public.legal_knowledge_versions;begin
 select * into r from public.legal_source_citations where id=p_id;if not found or not public._legal_assistance_actor(r.case_id,p_actor,r.category) then return false;end if;
 if r.source_kind='text_page' then
  select * into v from public.legal_document_text_versions where id=r.source_version_id and case_id=r.case_id and tenant_id=r.tenant_id and category=r.category and document_id=r.document_id and source_sha256=r.source_sha256;if not found or not public._legal_assistance_text_current(v.id,p_actor,r.page_number) then return false;end if;
  select * into p from public.legal_document_text_pages where version_id=v.id and page_number=r.page_number;return substr(p.text,r.start_offset,length(r.quote))=r.quote;
 end if;
 select * into k from public.legal_knowledge_versions where id=r.source_version_id and tenant_id=r.tenant_id and source_sha256=r.source_sha256;if not found or r.category<>'general' or not public._legal_assistance_knowledge_access(k.id,p_actor,true) then return false;end if;return substr(k.text,r.start_offset,length(r.quote))=r.quote;
end;$$;
create or replace function public._legal_assistance_validate_sources(p_case uuid,p_category text,p_citations uuid[],p_actor uuid,p_required boolean default false) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare citation_id uuid;r public.legal_source_citations;result jsonb:='[]';bytes integer:=0;begin
 if p_citations is null or cardinality(p_citations)>12 or (p_required and cardinality(p_citations)=0) or cardinality(p_citations)<>(select count(distinct x) from unnest(p_citations) x) then raise exception 'Unique bounded citation selection required' using errcode='22023';end if;
 foreach citation_id in array p_citations loop
  select * into r from public.legal_source_citations where legal_source_citations.id=citation_id and case_id=p_case;if not found or not public._legal_assistance_citation_valid(r.id,p_actor) or not(r.category='general' or r.category=p_category or p_category='restricted') then raise exception 'Current same-case literal citation and preserved category required' using errcode='42501';end if;
  bytes:=bytes+octet_length(r.quote);result:=result||jsonb_build_array(to_jsonb(r));
 end loop;
 if bytes>24000 then raise exception 'Selected source excerpts exceed 24k UTF8 bytes' using errcode='22023';end if;return result;
end;$$;
create or replace function public._legal_assistance_body(p_body jsonb,p_citations uuid[]) returns void language plpgsql immutable set search_path=pg_catalog,public,pg_temp as $$declare section jsonb;item jsonb;name text;begin
 perform public._legal_judicial_payload(p_body,array['title','sections','missing_facts','divergences']);if not(p_body ?& array['title','sections','missing_facts','divergences']) or jsonb_typeof(p_body->'title')<>'string' or length(btrim(p_body->>'title')) not between 1 and 200 or octet_length(p_body::text)>96000 or jsonb_typeof(p_body->'sections')<>'array' or jsonb_array_length(p_body->'sections') not between 1 and 12 then raise exception 'Bounded structured draft body required' using errcode='22023';end if;
 foreach name in array array['missing_facts','divergences'] loop if jsonb_typeof(p_body->name)<>'array' or jsonb_array_length(p_body->name)>20 then raise exception 'Bounded gap and divergence arrays required' using errcode='22023';end if;for item in select value from jsonb_array_elements(p_body->name) loop if jsonb_typeof(item)<>'string' or length(btrim(item#>>'{}')) not between 1 and 2000 then raise exception 'Explicit bounded gap text required' using errcode='22023';end if;end loop;end loop;
 for section in select value from jsonb_array_elements(p_body->'sections') loop
  perform public._legal_judicial_payload(section,array['heading','text','citation_ids']);if not(section ?& array['heading','text','citation_ids']) or jsonb_typeof(section->'heading')<>'string' or length(btrim(section->>'heading')) not between 1 and 200 or jsonb_typeof(section->'text')<>'string' or length(btrim(section->>'text')) not between 1 and 6000 or jsonb_typeof(section->'citation_ids')<>'array' or jsonb_array_length(section->'citation_ids')>12 then raise exception 'Bounded draft section required' using errcode='22023';end if;
  if (select count(distinct x) from jsonb_array_elements(section->'citation_ids') x)<>jsonb_array_length(section->'citation_ids') then raise exception 'Section citation IDs must be unique' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(section->'citation_ids') loop if jsonb_typeof(item)<>'string' or not((item#>>'{}')::uuid=any(p_citations)) then raise exception 'Unknown or unselected generated citation refused' using errcode='22023';end if;end loop;
 end loop;
end;$$;
create or replace function public._legal_assistance_snapshot(p_case uuid,p_category text,p_citations uuid[],p_actor uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare citations jsonb;begin
 citations:=public._legal_assistance_validate_sources(p_case,p_category,p_citations,p_actor);
 return jsonb_build_object('case_id',p_case,'category',p_category,'citations',citations,'source_states',coalesce((select jsonb_agg(jsonb_build_object('citation_id',c.id,'page_reviewer',p.reviewed_by,'page_reviewed_at',p.reviewed_at,'knowledge_reviewer',k.reviewed_by,'knowledge_reviewed_at',k.reviewed_at) order by c.id) from public.legal_source_citations c left join public.legal_document_text_pages p on c.source_kind='text_page' and p.version_id=c.source_version_id and p.page_number=c.page_number left join public.legal_knowledge_versions k on c.source_kind='knowledge' and k.id=c.source_version_id where c.id=any(p_citations)),'[]'));
end;$$;
create or replace function public._legal_assistance_draft_current(p_version uuid,p_actor uuid) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_assistance_draft_versions;begin
 select * into v from public.legal_assistance_draft_versions where id=p_version;if not found or v.state='revoked' or not public._legal_assistance_actor(v.case_id,p_actor,v.category) or exists(select 1 from public.legal_assistance_draft_versions n where n.case_id=v.case_id and n.draft_key=v.draft_key and n.version_number>v.version_number) then return false;end if;
 return v.snapshot_hash=encode(sha256(convert_to(public._legal_assistance_snapshot(v.case_id,v.category,v.citation_ids,p_actor)::text,'UTF8')),'hex');exception when insufficient_privilege or invalid_parameter_value then return false;
end;$$;

create or replace function public.legal_assistance_configure_ocr(p_enabled boolean,p_monthly_page_limit integer,p_max_pages integer) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public.legal_actual_tenant();r public.legal_assistance_settings;begin
 if not public._legal_judicial_admin() or p_enabled is null then raise exception 'Current workspace administration required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||t,0));if not public._legal_judicial_admin() or t is distinct from public.legal_actual_tenant() then raise exception 'Workspace administration revoked' using errcode='42501';end if;
 insert into public.legal_assistance_settings(tenant_id,ocr_enabled,ocr_monthly_page_limit,ocr_max_pages,updated_by) values(t,p_enabled,p_monthly_page_limit,p_max_pages,auth.uid()) on conflict(tenant_id) do update set ocr_enabled=excluded.ocr_enabled,ocr_monthly_page_limit=excluded.ocr_monthly_page_limit,ocr_max_pages=excluded.ocr_max_pages,updated_by=excluded.updated_by,updated_at=clock_timestamp() returning * into r;
 perform public._legal_assistance_event(t,null,'general','ocr_configured',jsonb_build_object('enabled',r.ocr_enabled));return to_jsonb(r);
end;$$;
create or replace function public.legal_ocr_enqueue(p_document_id uuid,p_idempotency_key uuid,p_previous_job_id uuid default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.legal_case_documents;r public.legal_ocr_jobs;old public.legal_ocr_jobs;s public.legal_assistance_settings;begin
 select * into d from public.legal_case_documents where id=p_document_id;perform public._legal_judicial_assert(d.case_id,d.category);perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||d.tenant_id,0));d:=public._legal_assistance_document(p_document_id,auth.uid(),true);
 select * into r from public.legal_ocr_jobs where tenant_id=d.tenant_id and idempotency_key=p_idempotency_key;if found then if r.document_id<>d.id then raise exception 'OCR idempotency mismatch' using errcode='22023';end if;return public._legal_assistance_projection(to_jsonb(r),'ocr_job');end if;
 select * into s from public.legal_assistance_settings where tenant_id=d.tenant_id;if not found or not s.ocr_enabled then raise exception 'Office OCR is not enabled' using errcode='22023';end if;
 if d.mime_type not in ('application/pdf','image/png') or d.size_bytes>10485760 then raise exception 'OCR accepts ready PDF or PNG up to 10MiB' using errcode='22023';end if;
 select * into old from public.legal_ocr_jobs where document_id=d.id order by created_at desc,id desc limit 1;
 if old.id is not null and (old.state in ('queued','running') or old.id is distinct from p_previous_job_id) then raise exception 'Reprocessing requires the latest terminal job reference' using errcode='22023';end if;
 if old.id is null and p_previous_job_id is not null then raise exception 'No previous OCR job for this document' using errcode='22023';end if;
 if (select coalesce(sum(quota_pages),0) from public.legal_ocr_jobs where tenant_id=d.tenant_id and quota_month=public._legal_assistance_month())+s.ocr_max_pages>s.ocr_monthly_page_limit then raise exception 'OCR monthly page reservation exceeded' using errcode='22023';end if;
 insert into public.legal_ocr_jobs(tenant_id,case_id,category,document_id,source_sha256,idempotency_key,state,max_pages,quota_pages,quota_month,base_version_id,created_by) values(d.tenant_id,d.case_id,d.category,d.id,d.sha256,p_idempotency_key,'queued',s.ocr_max_pages,s.ocr_max_pages,public._legal_assistance_month(),(select id from public.legal_document_text_versions where document_id=d.id order by version_number desc limit 1),auth.uid()) returning * into r;
 perform public._legal_assistance_event(d.tenant_id,d.case_id,d.category,'ocr_requested',jsonb_build_object('job_id',r.id));return public._legal_assistance_projection(to_jsonb(r),'ocr_job');
end;$$;
create or replace function public.legal_ocr_cancel(p_job_id uuid,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ocr_jobs;begin
 select * into r from public.legal_ocr_jobs where id=p_job_id;perform public._legal_judicial_assert(r.case_id,r.category);select * into r from public.legal_ocr_jobs where id=p_job_id for update;if r.state not in ('queued','running') or length(btrim(coalesce(p_note,''))) not between 1 and 2000 then raise exception 'Only pending OCR work can be cancelled with a reason' using errcode='22023';end if;
 update public.legal_ocr_jobs set state='cancelled',quota_pages=case when state='queued' then 0 else quota_pages end,error_code='cancelled_by_staff',finished_at=clock_timestamp(),updated_at=clock_timestamp() where id=r.id returning * into r;perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'ocr_cancelled',jsonb_build_object('job_id',r.id));return public._legal_assistance_projection(to_jsonb(r),'ocr_job');
end;$$;
create or replace function public.legal_ocr_service_claim(p_limit integer default 1) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ocr_jobs;d public.legal_case_documents;s public.legal_assistance_settings;begin
 perform public._legal_portal_service();if p_limit<>1 then raise exception 'Private OCR worker claims exactly one job' using errcode='22023';end if;
 for r in select * from public.legal_ocr_jobs where state in ('queued','running') order by created_at,id limit 50 loop
  perform 1 from public.legal_cases where id=r.case_id for update skip locked;if not found then continue;end if;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||r.tenant_id,0));select * into r from public.legal_ocr_jobs where id=r.id for update skip locked;if not found then continue;end if;
  if r.state='running' then if r.lease_until<=clock_timestamp() then update public.legal_ocr_jobs set state='unknown',error_code='lease_expired',lease_token=null,lease_until=null,finished_at=clock_timestamp() where id=r.id;end if;continue;end if;if r.state<>'queued' then continue;end if;
  select * into d from public.legal_case_documents where id=r.document_id;select * into s from public.legal_assistance_settings where tenant_id=r.tenant_id;
  if d.status<>'ready' or d.sha256 is distinct from r.source_sha256 or not public._legal_assistance_actor(r.case_id,r.created_by,r.category,true) or s.ocr_enabled is distinct from true then update public.legal_ocr_jobs set state='authorization_revoked',quota_pages=0,error_code='source_or_authorization_revoked',finished_at=clock_timestamp() where id=r.id;continue;end if;
  if r.quota_month<>public._legal_assistance_month() then
   if (select coalesce(sum(quota_pages),0) from public.legal_ocr_jobs where tenant_id=r.tenant_id and quota_month=public._legal_assistance_month())+r.quota_pages>s.ocr_monthly_page_limit then update public.legal_ocr_jobs set state='failed',quota_pages=0,error_code='monthly_page_limit',finished_at=clock_timestamp() where id=r.id;continue;end if;
   update public.legal_ocr_jobs set quota_month=public._legal_assistance_month() where id=r.id;
  end if;
  update public.legal_ocr_jobs set state='running',attempts=1,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '5 minutes',started_at=clock_timestamp(),updated_at=clock_timestamp() where id=r.id returning * into r;
  return jsonb_build_array(jsonb_build_object('id',r.id,'lease_token',r.lease_token,'document_id',d.id,'storage_path',d.storage_path,'source_sha256',r.source_sha256,'source_bytes',d.size_bytes,'mime_type',d.mime_type,'max_pages',r.max_pages,'tenant_id',r.tenant_id,'case_id',r.case_id,'category',r.category));
 end loop;return '[]';
end;$$;
create or replace function public._legal_assistance_kernel(p_result jsonb,p_job public.legal_ocr_jobs,p_document public.legal_case_documents) returns integer language plpgsql immutable set search_path=pg_catalog,public,pg_temp as $$declare p jsonb;w jsonb;processed integer:=0;total integer;begin
 perform public._legal_judicial_payload(p_result,array['kernel_version','source_sha256','source_bytes','mime_type','status','reason','pages_total','pages','engine','elapsed_ms','review_status']);
 if octet_length(p_result::text)>4194304 or p_result->>'kernel_version' is distinct from 'legal-ocr-offline-v1' or (jsonb_typeof(p_result->'status') is distinct from 'string' or p_result->>'status' not in ('complete','partial','unreadable','failed','refused')) or p_result->>'review_status' is distinct from 'unreviewed' or p_result->>'mime_type' is distinct from p_document.mime_type or jsonb_typeof(p_result->'pages') is distinct from 'array' or jsonb_array_length(p_result->'pages')>p_job.max_pages or coalesce(p_result->>'elapsed_ms','') !~ '^[0-9]{1,6}$' then raise exception 'Malformed bounded OCR kernel result' using errcode='22023';end if;
 if p_result->>'reason' is not null and p_result->>'reason' !~ '^[a-zA-Z0-9_:-]{1,100}$' then raise exception 'Normalized OCR reason required' using errcode='22023';end if;
 if p_result->>'source_sha256' is distinct from p_job.source_sha256 or p_result->>'source_bytes' is distinct from p_document.size_bytes::text then
  if p_result->>'status' not in ('refused','failed') or jsonb_array_length(p_result->'pages')<>0 or p_result->>'source_sha256' is not null or p_result->>'source_bytes' is not null then raise exception 'OCR bytes do not match authorized source' using errcode='22023';end if;
 end if;
 if p_result->>'pages_total' is not null then if p_result->>'pages_total' !~ '^[1-9][0-9]{0,6}$' then raise exception 'Known positive original page count required' using errcode='22023';end if;total:=(p_result->>'pages_total')::integer;end if;
 if jsonb_array_length(p_result->'pages')<>(select count(distinct value->>'page') from jsonb_array_elements(p_result->'pages')) then raise exception 'Duplicate OCR page number' using errcode='22023';end if;
 for p in select value from jsonb_array_elements(p_result->'pages') loop
  perform public._legal_judicial_payload(p,array['page','status','text','tsv','words','confidence_mean','width','height','coordinate_system','review_status','reason']);
  if coalesce(p->>'page','') !~ '^([1-9][0-9]{0,2}|1000)$' or (p->>'page')::integer>coalesce(total,1000) or (jsonb_typeof(p->'status') is distinct from 'string' or p->>'status' not in ('recognized','low_confidence','no_text_recognized','not_processed')) or (p->>'status'<>'not_processed' and p->>'coordinate_system' is distinct from 'rendered_pixels') or p->>'review_status' is distinct from 'unreviewed' then raise exception 'Invalid OCR page provenance' using errcode='22023';end if;
  if p->>'status'<>'not_processed' then processed:=processed+1;if jsonb_typeof(p->'text') is distinct from 'string' or octet_length(p->>'text')>524288 or coalesce(p->>'width','') !~ '^[1-9][0-9]{0,3}$' or coalesce(p->>'height','') !~ '^[1-9][0-9]{0,3}$' or (p->>'width')::integer>4000 or (p->>'height')::integer>4000 or jsonb_typeof(p->'words') is distinct from 'array' or jsonb_array_length(p->'words')>20000 then raise exception 'Bounded OCR page text, coordinates and words required' using errcode='22023';end if;
  elsif nullif(p->>'text','') is not null or coalesce(jsonb_array_length(p->'words'),0)>0 then raise exception 'Unprocessed page cannot invent recognized text' using errcode='22023';end if;
  if p->>'confidence_mean' is not null and (jsonb_typeof(p->'confidence_mean')<>'string' or p->>'confidence_mean' !~ '^[0-9]{1,3}(\.[0-9]{1,6})?$' or (p->>'confidence_mean')::numeric not between 0 and 100) then raise exception 'Mean confidence must be a bounded decimal string' using errcode='22023';end if;
  for w in select value from jsonb_array_elements(coalesce(p->'words','[]')) loop
   perform public._legal_judicial_payload(w,array['text','left','top','width','height','confidence','block','paragraph','line']);if jsonb_typeof(w->'text') is distinct from 'string' or length(w->>'text') not between 1 and 10000 or jsonb_typeof(w->'confidence') is distinct from 'string' or w->>'confidence' !~ '^-?[0-9]{1,3}(\.[0-9]{1,6})?$' or (w->>'confidence')::numeric not between -1 and 100 then raise exception 'Bounded OCR word and decimal confidence required' using errcode='22023';end if;
   if exists(select 1 from unnest(array['left','top','width','height','block','paragraph','line']) key where jsonb_typeof(w->key) is distinct from 'number' or coalesce(w->>key,'') !~ '^[0-9]{1,5}$') or (w->>'left')::integer+(w->>'width')::integer>(p->>'width')::integer or (w->>'top')::integer+(w->>'height')::integer>(p->>'height')::integer then raise exception 'OCR word coordinates must fit its rendered page' using errcode='22023';end if;
  end loop;
 end loop;
 if p_result->>'status'='complete' and (total is null or total<>jsonb_array_length(p_result->'pages') or exists(select 1 from generate_series(1,total) n where not exists(select 1 from jsonb_array_elements(p_result->'pages') x where (x->>'page')::integer=n and x->>'status'='recognized'))) then raise exception 'Complete OCR result must account for every recognized page' using errcode='22023';end if;
 if jsonb_array_length(p_result->'pages')>0 and (jsonb_typeof(p_result->'engine') is distinct from 'object' or not exists(select 1 from jsonb_array_elements(coalesce(p_result->'engine'->'models','[]')) model where model->>'language'='por' and model->>'sha256' ~ '^[0-9a-f]{64}$')) then raise exception 'Portuguese model hash provenance required' using errcode='22023';end if;return processed;
end;$$;
create or replace function public.legal_ocr_service_finish(p_job_id uuid,p_lease_token uuid,p_result jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ocr_jobs;d public.legal_case_documents;v public.legal_document_text_versions;p jsonb;used integer;charge integer;denied boolean;begin
 perform public._legal_portal_service();select * into r from public.legal_ocr_jobs where id=p_job_id;if not found then raise exception 'OCR job unavailable' using errcode='42501';end if;perform 1 from public.legal_cases where id=r.case_id for update;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||r.tenant_id,0));select * into r from public.legal_ocr_jobs where id=p_job_id for update;
 if p_lease_token is null or r.lease_token is distinct from p_lease_token or r.state not in ('running','cancelled') then raise exception 'Current OCR completion lease required' using errcode='42501';end if;
 select * into d from public.legal_case_documents where id=r.document_id;used:=public._legal_assistance_kernel(p_result,r,d);
 charge:=case when exists(select 1 from jsonb_array_elements(p_result->'pages') page where page->>'status'='not_processed') or (p_result->>'status'='failed' and used=0) then greatest(used,least(r.max_pages,coalesce((p_result->>'pages_total')::integer,r.max_pages))) else used end;
 denied:=r.state='cancelled' or r.lease_until<=clock_timestamp() or d.status<>'ready' or d.sha256 is distinct from r.source_sha256 or not public._legal_assistance_actor(r.case_id,r.created_by,r.category,true) or not exists(select 1 from public.legal_assistance_settings where tenant_id=r.tenant_id and ocr_enabled);
 if denied then
  update public.legal_ocr_jobs set state=case when state='cancelled' then 'cancelled' else 'authorization_revoked' end,quota_pages=charge,processed_pages=used,error_code='completion_authorization_revoked',lease_token=null,lease_until=null,finished_at=clock_timestamp(),updated_at=clock_timestamp() where id=r.id returning * into r;
 elsif (select id from public.legal_document_text_versions where document_id=r.document_id order by version_number desc limit 1) is distinct from r.base_version_id then
  update public.legal_ocr_jobs set state='failed',quota_pages=charge,processed_pages=used,error_code='text_version_changed',lease_token=null,lease_until=null,finished_at=clock_timestamp() where id=r.id returning * into r;
 else
  if jsonb_array_length(p_result->'pages')>0 and (p_result->>'pages_total')::integer<=1000 then
   insert into public.legal_document_text_versions(tenant_id,case_id,category,document_id,source_sha256,version_number,mode,previous_version_id,ocr_job_id,pages_total,completeness,engine,created_by)
    select r.tenant_id,r.case_id,r.category,r.document_id,r.source_sha256,coalesce(max(version_number),0)+1,'ocr',r.base_version_id,r.id,(p_result->>'pages_total')::integer,case when p_result->>'status'='complete' then 'complete' else 'partial' end,p_result->'engine',r.created_by from public.legal_document_text_versions where document_id=r.document_id returning * into v;
   for p in select value from jsonb_array_elements(p_result->'pages') loop
    insert into public.legal_document_text_pages(tenant_id,case_id,version_id,category,page_number,text,page_status,words,confidence_mean,width,height) values(r.tenant_id,r.case_id,v.id,r.category,(p->>'page')::integer,p->>'text',p->>'status',coalesce(p->'words','[]'),p->>'confidence_mean',(p->>'width')::integer,(p->>'height')::integer);
   end loop;
  end if;
  update public.legal_ocr_jobs set state=case when p_result->>'status'='complete' then 'succeeded' when v.id is not null then 'partial' else 'failed' end,quota_pages=charge,pages_total=(p_result->>'pages_total')::integer,processed_pages=used,kernel_version=p_result->>'kernel_version',error_code=p_result->>'reason',result_version_id=v.id,result_sha256=encode(sha256(convert_to(p_result::text,'UTF8')),'hex'),lease_token=null,lease_until=null,finished_at=clock_timestamp(),updated_at=clock_timestamp() where id=r.id returning * into r;
 end if;
 perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'ocr_finished',jsonb_build_object('job_id',r.id,'state',r.state,'processed_pages',r.processed_pages),r.created_by);return jsonb_build_object('job',public._legal_assistance_projection(to_jsonb(r),'ocr_job'),'version_id',v.id);
end;$$;
create or replace function public.legal_ocr_service_fail(p_job_id uuid,p_lease_token uuid,p_code text,p_processing_started boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ocr_jobs;begin
 perform public._legal_portal_service();select * into r from public.legal_ocr_jobs where id=p_job_id;perform 1 from public.legal_cases where id=r.case_id for update;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||r.tenant_id,0));select * into r from public.legal_ocr_jobs where id=p_job_id for update;
 if p_lease_token is null or r.lease_token is distinct from p_lease_token or r.state not in ('running','cancelled') or p_processing_started is null or p_code !~ '^[a-zA-Z0-9_:-]{1,100}$' then raise exception 'Current OCR lease and normalized failure required' using errcode='42501';end if;
 update public.legal_ocr_jobs set state=case when state='cancelled' then state when p_processing_started then 'unknown' else 'failed' end,quota_pages=case when p_processing_started then quota_pages else 0 end,error_code=p_code,lease_token=null,lease_until=null,finished_at=clock_timestamp(),updated_at=clock_timestamp() where id=r.id returning * into r;
 perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'ocr_failed',jsonb_build_object('job_id',r.id,'state',r.state),r.created_by);return public._legal_assistance_projection(to_jsonb(r),'ocr_job');
end;$$;

create or replace function public.legal_text_create_version(p_document_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare d public.legal_case_documents;v public.legal_document_text_versions;old public.legal_document_text_versions;p jsonb;total integer;begin
 select * into d from public.legal_case_documents where id=p_document_id;perform public._legal_judicial_assert(d.case_id,d.category);d:=public._legal_assistance_document(p_document_id,auth.uid(),true);perform public._legal_judicial_payload(p_payload,array['mode','previous_version_id','pages_total','note','pages']);
 if p_payload->>'mode' not in ('manual','correction') or length(btrim(coalesce(p_payload->>'note',''))) not between 1 and 4000 or jsonb_typeof(p_payload->'pages') is distinct from 'array' or jsonb_array_length(p_payload->'pages') not between 1 and 20 or octet_length(p_payload::text)>2097152 then raise exception 'Bounded complete transcription version required' using errcode='22023';end if;
 if p_payload->>'pages_total' is not null then if p_payload->>'pages_total' !~ '^[1-9][0-9]{0,3}$' or (p_payload->>'pages_total')::integer>1000 then raise exception 'Original page count must be explicit and bounded' using errcode='22023';end if;total:=(p_payload->>'pages_total')::integer;end if;
 select * into old from public.legal_document_text_versions where document_id=d.id order by version_number desc limit 1;
 if old.id is distinct from (p_payload->>'previous_version_id')::uuid or (old.id is not null and p_payload->>'mode'<>'correction') or (old.id is null and p_payload->>'mode'<>'manual') then raise exception 'Correction must reference the latest full transcription version' using errcode='22023';end if;
 if jsonb_array_length(p_payload->'pages')<>(select count(distinct value->>'page_number') from jsonb_array_elements(p_payload->'pages')) then raise exception 'Duplicate manual page number' using errcode='22023';end if;
 for p in select value from jsonb_array_elements(p_payload->'pages') loop perform public._legal_judicial_payload(p,array['page_number','text']);if coalesce(p->>'page_number','') !~ '^([1-9][0-9]{0,2}|1000)$' or (p->>'page_number')::integer>coalesce(total,1000) or jsonb_typeof(p->'text') is distinct from 'string' or octet_length(p->>'text')>524288 then raise exception 'Explicit bounded original page and transcription text required' using errcode='22023';end if;end loop;
 if old.pages_total is not null and total is distinct from old.pages_total then raise exception 'Correction must preserve the known original page count; missing pages remain incomplete' using errcode='22023';end if;
 if old.id is not null and exists(select 1 from public.legal_document_text_pages prior where prior.version_id=old.id and prior.page_status in ('recognized','low_confidence','manual') and not exists(select 1 from jsonb_array_elements(p_payload->'pages') supplied where (supplied->>'page_number')::integer=prior.page_number)) then raise exception 'Correction cannot silently drop a previously transcribed page' using errcode='22023';end if;
 insert into public.legal_document_text_versions(tenant_id,case_id,category,document_id,source_sha256,version_number,mode,previous_version_id,pages_total,completeness,engine,note,created_by) values(d.tenant_id,d.case_id,d.category,d.id,d.sha256,coalesce(old.version_number,0)+1,p_payload->>'mode',old.id,total,case when total is null then 'unknown' when total=jsonb_array_length(p_payload->'pages') then 'complete' else 'partial' end,'{"source":"manual_transcription"}',p_payload->>'note',auth.uid()) returning * into v;
 for p in select value from jsonb_array_elements(p_payload->'pages') loop insert into public.legal_document_text_pages(tenant_id,case_id,version_id,category,page_number,text,page_status,coordinate_system) values(d.tenant_id,d.case_id,v.id,d.category,(p->>'page_number')::integer,p->>'text','manual','not_applicable');end loop;
 perform public._legal_assistance_event(d.tenant_id,d.case_id,d.category,'text_version_created',jsonb_build_object('version_id',v.id));return public._legal_assistance_projection(to_jsonb(v),'text_version');
end;$$;
create or replace function public.legal_text_list_pages(p_version_id uuid,p_limit integer default 20,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_document_text_versions;begin
 select * into v from public.legal_document_text_versions where id=p_version_id;if not found or not public._legal_assistance_actor(v.case_id,auth.uid(),v.category) then raise exception 'Text version access denied' using errcode='42501';end if;if p_limit not between 1 and 50 or p_offset not between 0 and 100000 then raise exception 'Bounded page list required' using errcode='22023';end if;
 return jsonb_build_object('items',coalesce((select jsonb_agg(public._legal_assistance_projection(to_jsonb(p),'text_page') order by page_number) from (select * from public.legal_document_text_pages where version_id=v.id order by page_number limit p_limit offset p_offset) p),'[]'),'has_more',(select count(*)>p_limit+p_offset from public.legal_document_text_pages where version_id=v.id));
end;$$;
create or replace function public.legal_text_read_page(p_version_id uuid,p_page_number integer) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_document_text_versions;p public.legal_document_text_pages;d public.legal_case_documents;begin
 select * into v from public.legal_document_text_versions where id=p_version_id;perform 1 from public.legal_cases where id=v.case_id for update;d:=public._legal_assistance_document(v.document_id,auth.uid());select * into v from public.legal_document_text_versions where id=p_version_id;if v.state='revoked' or d.sha256<>v.source_sha256 then raise exception 'Text source revoked or changed' using errcode='42501';end if;select * into p from public.legal_document_text_pages where version_id=v.id and page_number=p_page_number;if not found then raise exception 'Text page not present' using errcode='22023';end if;
 perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'text_page_read',jsonb_build_object('version_id',v.id,'page',p_page_number));return jsonb_build_object('version',public._legal_assistance_projection(to_jsonb(v),'text_version'),'page',to_jsonb(p),'is_current',public._legal_assistance_text_current(v.id,auth.uid()));
end;$$;
create or replace function public.legal_text_submit(p_version_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_document_text_versions;begin
 select * into v from public.legal_document_text_versions where id=p_version_id;perform public._legal_judicial_assert(v.case_id,v.category);select * into v from public.legal_document_text_versions where id=p_version_id for update;if v.state not in ('draft','returned') or not public._legal_assistance_text_current(v.id,auth.uid()) then raise exception 'Current text draft required' using errcode='22023';end if;
 update public.legal_document_text_versions set state='in_review' where id=v.id returning * into v;perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'text_submitted',jsonb_build_object('version_id',v.id));return public._legal_assistance_projection(to_jsonb(v),'text_version');
end;$$;
create or replace function public.legal_text_review_pages(p_version_id uuid,p_page_numbers integer[],p_decision text,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_document_text_versions;page_no integer;begin
 select * into v from public.legal_document_text_versions where id=p_version_id;perform public._legal_judicial_assert(v.case_id,v.category,true);select * into v from public.legal_document_text_versions where id=p_version_id for update;
 if v.state not in ('in_review','approved') or not public._legal_assistance_text_current(v.id,auth.uid()) or p_decision not in ('approved','returned') or cardinality(p_page_numbers) not between 1 and 20 or length(btrim(coalesce(p_note,''))) not between 1 and 4000 or cardinality(p_page_numbers)<>(select count(distinct x) from unnest(p_page_numbers) x) then raise exception 'Current submitted pages and explicit nominal review required' using errcode='22023';end if;
 foreach page_no in array p_page_numbers loop
  if not exists(select 1 from public.legal_document_text_pages where version_id=v.id and page_number=page_no and (p_decision='returned' or page_status<>'not_processed')) then raise exception 'Absent or unprocessed page cannot be approved' using errcode='22023';end if;
  update public.legal_document_text_pages set review_state=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=btrim(p_note) where version_id=v.id and page_number=page_no;insert into public.legal_document_text_reviews(tenant_id,case_id,version_id,page_number,decision,note,reviewed_by) values(v.tenant_id,v.case_id,v.id,page_no,p_decision,btrim(p_note),auth.uid());
 end loop;
 update public.legal_document_text_versions set state=case when p_decision='returned' then 'returned' when pages_total=(select count(*) from public.legal_document_text_pages where version_id=v.id and review_state='approved') and completeness='complete' then 'approved' else 'in_review' end,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=btrim(p_note) where id=v.id returning * into v;
 perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'text_pages_reviewed',jsonb_build_object('version_id',v.id,'pages',p_page_numbers,'decision',p_decision));return public._legal_assistance_projection(to_jsonb(v),'text_version');
end;$$;
create or replace function public.legal_text_revoke(p_version_id uuid,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_document_text_versions;begin
 select * into v from public.legal_document_text_versions where id=p_version_id;perform public._legal_judicial_assert(v.case_id,v.category,true);if length(btrim(coalesce(p_note,''))) not between 1 and 4000 then raise exception 'Revocation reason required' using errcode='22023';end if;
 update public.legal_document_text_versions set state='revoked',reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=btrim(p_note) where id=v.id returning * into v;perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'text_revoked',jsonb_build_object('version_id',v.id));return public._legal_assistance_projection(to_jsonb(v),'text_version');
end;$$;
create or replace function public.legal_knowledge_create_version(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public.legal_actual_tenant();r public.legal_knowledge_versions;d public.legal_case_documents;begin
 if not public.legal_can_create() then raise exception 'Knowledge catalog editing required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||t,0));if not public.legal_can_create() or t is distinct from public.legal_actual_tenant() then raise exception 'Knowledge editing revoked' using errcode='42501';end if;
 perform public._legal_judicial_payload(p_payload,array['knowledge_key','title','kind','source_url','source_document_id','checked_on','version_note','scope','text']);r.id:=gen_random_uuid();r.tenant_id:=t;r.created_by:=auth.uid();r.created_at:=clock_timestamp();r.state:='draft';r.review_note:='';r.source_url:='';r:=jsonb_populate_record(r,p_payload);r.checked_on:=public._legal_judicial_date(p_payload->>'checked_on');
 if r.source_document_id is not null then d:=public._legal_assistance_document(r.source_document_id,auth.uid());if d.tenant_id<>t or d.category<>'general' then raise exception 'Library cannot declassify medical or fiscal documents' using errcode='42501';end if;r.source_document_sha256:=d.sha256;end if;
 if nullif(r.source_url,'') is not null and r.source_url !~ '^https://[^[:space:]]+$' then raise exception 'HTTPS editorial origin required' using errcode='22023';end if;r.source_sha256:=encode(sha256(convert_to(r.text,'UTF8')),'hex');select coalesce(max(version_number),0)+1 into r.version_number from public.legal_knowledge_versions where tenant_id=t and knowledge_key=r.knowledge_key;
 insert into public.legal_knowledge_versions values(r.*) returning * into r;perform public._legal_assistance_event(t,null,'general','knowledge_drafted',jsonb_build_object('version_id',r.id));return public._legal_assistance_projection(to_jsonb(r),'knowledge');
end;$$;
create or replace function public.legal_knowledge_review(p_version_id uuid,p_decision text,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_knowledge_versions;t uuid:=public.legal_actual_tenant();begin
 if not public._legal_judicial_admin() then raise exception 'Knowledge review administration required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||t,0));if not public._legal_judicial_admin() or t is distinct from public.legal_actual_tenant() then raise exception 'Knowledge review revoked' using errcode='42501';end if;select * into r from public.legal_knowledge_versions where id=p_version_id and tenant_id=t for update;
 if not found or not public._legal_assistance_knowledge_access(r.id,auth.uid()) then raise exception 'Knowledge source unavailable' using errcode='42501';end if;
 if p_decision not in ('approved','rejected','revoked') or length(btrim(coalesce(p_note,''))) not between 1 and 4000 or (p_decision='revoked' and r.state<>'approved') or (p_decision<>'revoked' and r.state<>'draft') then raise exception 'Explicit knowledge review transition required' using errcode='22023';end if;
 if p_decision='approved' and (r.checked_on is null or r.checked_on>public._ir4_today() or (r.source_document_id is null and nullif(r.source_url,'') is null) or exists(select 1 from public.legal_knowledge_versions n where n.tenant_id=t and n.knowledge_key=r.knowledge_key and n.version_number>r.version_number)) then raise exception 'Current knowledge version, documented origin and checked date required' using errcode='22023';end if;
 update public.legal_knowledge_versions set state=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=btrim(p_note) where id=r.id returning * into r;perform public._legal_assistance_event(t,null,'general','knowledge_reviewed',jsonb_build_object('version_id',r.id,'decision',p_decision));return public._legal_assistance_projection(to_jsonb(r),'knowledge');
end;$$;
create or replace function public.legal_knowledge_read(p_version_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_knowledge_versions;begin
 select * into r from public.legal_knowledge_versions where id=p_version_id;if r.source_document_id is not null then perform 1 from public.legal_cases where id=(select case_id from public.legal_case_documents where id=r.source_document_id) for update;end if;
 if not public._legal_assistance_knowledge_access(p_version_id,auth.uid()) then raise exception 'Current knowledge origin access required' using errcode='42501';end if;select * into r from public.legal_knowledge_versions where id=p_version_id;
 perform public._legal_assistance_event(r.tenant_id,null,'general','knowledge_read',jsonb_build_object('version_id',r.id));return jsonb_build_object('version',to_jsonb(r)-'source_document_sha256','is_current',public._legal_assistance_knowledge_access(r.id,auth.uid(),true));
end;$$;
create or replace function public.legal_assistance_search(p_case_id uuid,p_query text,p_sources jsonb,p_limit integer default 10) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public._legal_judicial_assert(p_case_id,'general');source jsonb;selected_version public.legal_document_text_versions;candidate record;r public.legal_source_citations;result jsonb:='[]';n integer:=0;more boolean:=false;begin
 if length(btrim(coalesce(p_query,''))) not between 2 and 200 or p_limit not between 1 and 10 or jsonb_typeof(p_sources) is distinct from 'array' or jsonb_array_length(p_sources) not between 1 and 20 then raise exception 'Explicit bounded source selection and literal query required' using errcode='22023';end if;
 -- Validate every selected source before examining its text; selection is not an authorization.
 for source in select value from jsonb_array_elements(p_sources) loop
  perform public._legal_judicial_payload(source,array['kind','version_id']);if source->>'kind'='text_page' then
   select * into selected_version from public.legal_document_text_versions where id=(source->>'version_id')::uuid and case_id=p_case_id;if not found or not public._legal_assistance_text_current(selected_version.id,auth.uid()) then raise exception 'Selected text source unavailable' using errcode='42501';end if;
  elsif source->>'kind'='knowledge' then if not public._legal_assistance_knowledge_access((source->>'version_id')::uuid,auth.uid(),true) then raise exception 'Selected knowledge source unavailable' using errcode='42501';end if;
  else raise exception 'Unknown selected source kind' using errcode='22023';end if;
 end loop;
 for candidate in
  with authorized as materialized(
   select 'text_page'::text kind,v.id version_id,v.document_id,p.page_number,v.category,p.text,v.source_sha256,d.display_name label from public.legal_document_text_versions v join public.legal_document_text_pages p on p.version_id=v.id join public.legal_case_documents d on d.id=v.document_id where v.case_id=p_case_id and exists(select 1 from jsonb_array_elements(p_sources) x where x->>'kind'='text_page' and (x->>'version_id')::uuid=v.id) and public._legal_assistance_text_current(v.id,auth.uid(),p.page_number)
   union all select 'knowledge',k.id,k.source_document_id,null::integer,'general',k.text,k.source_sha256,k.title from public.legal_knowledge_versions k where k.tenant_id=t and exists(select 1 from jsonb_array_elements(p_sources) x where x->>'kind'='knowledge' and (x->>'version_id')::uuid=k.id) and public._legal_assistance_knowledge_access(k.id,auth.uid(),true)
  ) select *,greatest(1,strpos(lower(text),lower(p_query))-120) quote_start from authorized where strpos(lower(text),lower(p_query))>0 order by kind,version_id,page_number limit p_limit+1
 loop
  if n>=p_limit then more:=true;exit;end if;
  insert into public.legal_source_citations(tenant_id,case_id,category,source_kind,source_version_id,document_id,page_number,start_offset,quote,source_sha256,source_label,created_by) values(t,p_case_id,candidate.category,candidate.kind,candidate.version_id,candidate.document_id,candidate.page_number,candidate.quote_start,substr(candidate.text,candidate.quote_start,3000),candidate.source_sha256,left(candidate.label,200),auth.uid()) returning * into r;
  result:=result||jsonb_build_array(to_jsonb(r));n:=n+1;
 end loop;
 perform public._legal_assistance_event(t,p_case_id,'restricted','sources_searched',jsonb_build_object('returned',n));return jsonb_build_object('citations',result,'has_more',more);
end;$$;
create or replace function public.legal_assistance_read_citation(p_citation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_source_citations;begin
 select * into r from public.legal_source_citations where id=p_citation_id;perform 1 from public.legal_cases where id=r.case_id for update;if not public._legal_assistance_citation_valid(p_citation_id,auth.uid()) then raise exception 'Citation source, page, hash or permission changed' using errcode='42501';end if;
 perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'citation_read',jsonb_build_object('citation_id',r.id));return to_jsonb(r);
end;$$;
create or replace function public._legal_assistance_insert_draft(p_case_id uuid,p_payload jsonb,p_actor uuid,p_mode text,p_ai_job uuid default null) returns public.legal_assistance_draft_versions language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_assistance_draft_versions;old public.legal_assistance_draft_versions;begin
 perform public._legal_judicial_payload(p_payload,array['draft_key','kind','category','purpose','body','citation_ids','previous_version_id']);if not public._legal_assistance_actor(p_case_id,p_actor,p_payload->>'category',true) then raise exception 'Draft category edit access required' using errcode='42501';end if;
 r.id:=gen_random_uuid();r.case_id:=p_case_id;select tenant_id into r.tenant_id from public.legal_cases where id=p_case_id;r.created_by:=p_actor;r.created_at:=clock_timestamp();r.state:='draft';r.mode:=p_mode;r.ai_job_id:=p_ai_job;r.review_note:='';r.citation_ids:='{}';r:=jsonb_populate_record(r,p_payload);
 if not(p_payload?'citation_ids') or jsonb_typeof(p_payload->'citation_ids')<>'array' then raise exception 'Explicit citation selection required, including empty manual source list' using errcode='22023';end if;
 perform public._legal_assistance_body(r.body,r.citation_ids);r.snapshot:=public._legal_assistance_snapshot(p_case_id,r.category,r.citation_ids,p_actor);r.snapshot_hash:=encode(sha256(convert_to(r.snapshot::text,'UTF8')),'hex');
 select * into old from public.legal_assistance_draft_versions where case_id=p_case_id and draft_key=r.draft_key order by version_number desc limit 1;
 if old.id is distinct from r.previous_version_id then raise exception 'New draft version must explicitly reference its latest predecessor' using errcode='22023';end if;if old.id is not null and old.category<>r.category then raise exception 'A draft series preserves its original category; create a separate series' using errcode='22023';end if;r.version_number:=coalesce(old.version_number,0)+1;
 insert into public.legal_assistance_draft_versions values(r.*) returning * into r;perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'draft_created',jsonb_build_object('version_id',r.id,'mode',p_mode),p_actor);return r;
end;$$;
create or replace function public.legal_assistance_create_draft(p_case_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_assistance_draft_versions;begin
 perform public._legal_judicial_assert(p_case_id,p_payload->>'category');perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||public.legal_actual_tenant(),0));r:=public._legal_assistance_insert_draft(p_case_id,p_payload,auth.uid(),'manual');return public._legal_assistance_projection(to_jsonb(r),'draft')||jsonb_build_object('is_current',true);
end;$$;
create or replace function public.legal_assistance_read_draft(p_version_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_assistance_draft_versions;citations jsonb;begin
 select * into v from public.legal_assistance_draft_versions where id=p_version_id;perform 1 from public.legal_cases where id=v.case_id for update;select * into v from public.legal_assistance_draft_versions where id=p_version_id;
 if v.state='revoked' or not public._legal_assistance_actor(v.case_id,auth.uid(),v.category) then raise exception 'Current draft category access required' using errcode='42501';end if;citations:=public._legal_assistance_validate_sources(v.case_id,v.category,v.citation_ids,auth.uid());
 perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'draft_read',jsonb_build_object('version_id',v.id));return jsonb_build_object('version',to_jsonb(v),'citations',citations,'is_current',public._legal_assistance_draft_current(v.id,auth.uid()));
end;$$;
create or replace function public.legal_assistance_submit(p_version_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_assistance_draft_versions;begin
 select * into v from public.legal_assistance_draft_versions where id=p_version_id;perform public._legal_judicial_assert(v.case_id,v.category);perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||v.tenant_id,0));select * into v from public.legal_assistance_draft_versions where id=p_version_id for update;
 if v.state not in ('draft','returned') or not public._legal_assistance_draft_current(v.id,auth.uid()) then raise exception 'Current sourced draft required for review' using errcode='22023';end if;update public.legal_assistance_draft_versions set state='in_review' where id=v.id returning * into v;perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'draft_submitted',jsonb_build_object('version_id',v.id));return public._legal_assistance_projection(to_jsonb(v),'draft')||jsonb_build_object('is_current',true);
end;$$;
create or replace function public.legal_assistance_review(p_version_id uuid,p_decision text,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_assistance_draft_versions;begin
 select * into v from public.legal_assistance_draft_versions where id=p_version_id;perform public._legal_judicial_assert(v.case_id,v.category,true);perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||v.tenant_id,0));select * into v from public.legal_assistance_draft_versions where id=p_version_id for update;perform public._legal_judicial_assert(v.case_id,v.category,true);
 if p_decision not in ('reviewed','returned','revoked') or length(btrim(coalesce(p_note,''))) not between 1 and 4000 or (p_decision='revoked' and v.state<>'reviewed') or (p_decision='reviewed' and (v.state<>'in_review' or not public._legal_assistance_draft_current(v.id,auth.uid()))) or (p_decision='returned' and v.state not in ('draft','in_review')) then raise exception 'Explicit current sourced review or revocation required' using errcode='22023';end if;
 update public.legal_assistance_draft_versions set state=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=btrim(p_note) where id=v.id returning * into v;insert into public.legal_assistance_draft_reviews(tenant_id,case_id,version_id,decision,note,reviewed_by) values(v.tenant_id,v.case_id,v.id,p_decision,btrim(p_note),auth.uid());
 perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'draft_reviewed',jsonb_build_object('version_id',v.id,'decision',p_decision));return public._legal_assistance_projection(to_jsonb(v),'draft')||jsonb_build_object('is_current',public._legal_assistance_draft_current(v.id,auth.uid()));
end;$$;
create or replace function public.legal_assistance_use_draft(p_version_id uuid,p_target_kind text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_assistance_draft_versions;target uuid;body_text text;begin
 select * into v from public.legal_assistance_draft_versions where id=p_version_id;perform public._legal_judicial_assert(v.case_id,v.category,true);perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||v.tenant_id,0));select * into v from public.legal_assistance_draft_versions where id=p_version_id;
 if v.state<>'reviewed' or not public._legal_assistance_draft_current(v.id,auth.uid()) or v.category='restricted' then raise exception 'Current reviewed single-category draft required for explicit use' using errcode='22023';end if;
 select string_agg((value->>'heading')||E'\n'||(value->>'text'),E'\n\n' order by ordinality) into body_text from jsonb_array_elements(v.body->'sections') with ordinality;
 if p_target_kind='instrument' then perform public._legal_judicial_payload(p_payload,array['instrument_type','title']);target:=(public.legal_create_instrument(v.case_id,p_payload->>'instrument_type',p_payload->>'title',v.category,body_text)).id;
 elsif p_target_kind='publication' then perform public._legal_judicial_payload(p_payload,array['membership_id','title','publication_kind']);if p_payload->>'publication_kind' not in ('summary','update') then raise exception 'Only reviewed summary/update can become a portal draft' using errcode='22023';end if;target:=(public.legal_create_portal_publication(v.case_id,p_payload||jsonb_build_object('category',v.category,'body',body_text))).id;
 else raise exception 'Explicit instrument or publication target required' using errcode='22023';end if;
 insert into public.legal_assistance_transfers(tenant_id,case_id,version_id,target_kind,target_id,created_by) values(v.tenant_id,v.case_id,v.id,p_target_kind,target,auth.uid());perform public._legal_assistance_event(v.tenant_id,v.case_id,v.category,'draft_used',jsonb_build_object('version_id',v.id,'target_kind',p_target_kind,'target_id',target));return jsonb_build_object('target_kind',p_target_kind,'target_id',target,'source_version_id',v.id);
end;$$;
create or replace function public._legal_assistance_decimal(p_value jsonb,p_scale integer) returns numeric language plpgsql immutable set search_path=pg_catalog,public,pg_temp as $$declare s text:=p_value#>>'{}';begin
 if jsonb_typeof(p_value) is distinct from 'string' or s is null or s !~ ('^(0|[1-9][0-9]{0,9})(\.[0-9]{1,'||p_scale||'})?$') then raise exception 'Canonical finite nonnegative decimal string required' using errcode='22023';end if;return s::numeric;
end;$$;
create or replace function public._legal_assistance_policy_allowed(p_version uuid,p_category text) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
 select exists(select 1 from public.legal_ai_policy_versions v join public.profiles reviewer on reviewer.id=v.reviewed_by and reviewer.tenant_id=v.tenant_id and reviewer.status='active' and reviewer.role='admin' join public.legal_case_documents d on d.id=v.source_document_id and d.tenant_id=v.tenant_id and d.category='general' and d.status='ready' and d.sha256=v.source_document_sha256 where v.id=p_version and v.state='approved' and public._ir4_today() between v.valid_from and v.valid_until and public._legal_assistance_actor(d.case_id,reviewer.id,'general') and not exists(select 1 from public.legal_ai_policy_versions n where n.tenant_id=v.tenant_id and n.policy_key=v.policy_key and n.version_number>v.version_number and n.state='approved') and (p_category='general' or p_category='medical' and v.allow_medical or p_category='fiscal' and v.allow_fiscal or p_category='restricted' and v.allow_medical and v.allow_fiscal));
$$;
create or replace function public.legal_ai_create_policy_version(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public.legal_actual_tenant();r public.legal_ai_policy_versions;d public.legal_case_documents;begin
 if not public._legal_judicial_admin() then raise exception 'AI policy administration required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||t,0));if not public._legal_judicial_admin() or t is distinct from public.legal_actual_tenant() then raise exception 'Policy administration revoked' using errcode='42501';end if;
 perform public._legal_judicial_payload(p_payload,array['policy_key','title','model','purpose_note','retention_note','source_document_id','source_url','checked_on','valid_from','valid_until','allow_medical','allow_fiscal','currency','rate_unit','input_rate','output_rate','monthly_budget','max_input_tokens','max_output_tokens']);
 r.id:=gen_random_uuid();r.tenant_id:=t;r.created_by:=auth.uid();r.created_at:=clock_timestamp();r.state:='draft';r.review_note:='';r.allow_medical:=false;r.allow_fiscal:=false;r:=jsonb_populate_record(r,p_payload);r.input_rate:=public._legal_assistance_decimal(p_payload->'input_rate',8);r.output_rate:=public._legal_assistance_decimal(p_payload->'output_rate',8);r.monthly_budget:=public._legal_assistance_decimal(p_payload->'monthly_budget',6);r.checked_on:=public._legal_judicial_date(p_payload->>'checked_on');r.valid_from:=public._legal_judicial_date(p_payload->>'valid_from');r.valid_until:=public._legal_judicial_date(p_payload->>'valid_until');
 if r.source_document_id is not null then d:=public._legal_assistance_document(r.source_document_id,auth.uid());if d.tenant_id<>t or d.category<>'general' then raise exception 'AI policy requires a same-tenant general proof' using errcode='42501';end if;r.source_document_sha256:=d.sha256;end if;
 select coalesce(max(version_number),0)+1 into r.version_number from public.legal_ai_policy_versions where tenant_id=t and policy_key=r.policy_key;insert into public.legal_ai_policy_versions values(r.*) returning * into r;perform public._legal_assistance_event(t,null,'general','ai_policy_drafted',jsonb_build_object('version_id',r.id));return public._legal_assistance_projection(to_jsonb(r),'ai_policy');
end;$$;
create or replace function public.legal_ai_review_policy(p_version_id uuid,p_decision text,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ai_policy_versions;d public.legal_case_documents;t uuid:=public.legal_actual_tenant();begin
 if not public._legal_judicial_admin() then raise exception 'AI policy review administration required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||t,0));if not public._legal_judicial_admin() or t is distinct from public.legal_actual_tenant() then raise exception 'AI policy administration revoked' using errcode='42501';end if;
 select * into r from public.legal_ai_policy_versions where id=p_version_id and tenant_id=t for update;if not found then raise exception 'AI policy access denied' using errcode='42501';end if;
 if p_decision not in ('approved','rejected','revoked') or length(btrim(coalesce(p_note,''))) not between 1 and 4000 or (p_decision='revoked' and r.state<>'approved') or (p_decision<>'revoked' and r.state<>'draft') then raise exception 'Explicit AI policy review transition required' using errcode='22023';end if;
 if p_decision='approved' then d:=public._legal_assistance_document(r.source_document_id,auth.uid());if d.category<>'general' or d.tenant_id<>t or d.sha256 is distinct from r.source_document_sha256 or r.source_url !~ '^https://[^[:space:]]+$' or r.checked_on is null or r.checked_on>public._ir4_today() or r.valid_from is null or r.valid_until is null then raise exception 'Policy approval requires current proof, source, rates and finite validity' using errcode='22023';end if;end if;
 update public.legal_ai_policy_versions set state=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=btrim(p_note) where id=r.id returning * into r;perform public._legal_assistance_event(t,null,'general','ai_policy_reviewed',jsonb_build_object('version_id',r.id,'decision',p_decision));return public._legal_assistance_projection(to_jsonb(r),'ai_policy');
end;$$;
create or replace function public.legal_ai_service_configure(p_actor_id uuid,p_expected_tenant_id uuid,p_account_id text,p_model text,p_policy_version_id uuid,p_enabled boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare c public.legal_ai_connections;p public.legal_ai_policy_versions;begin
 perform public._legal_portal_service();perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||p_expected_tenant_id,0));perform pg_advisory_xact_lock(hashtextextended('legal_ai_account:'||p_account_id,0));
 if not public._legal_judicial_admin(p_actor_id) or p_expected_tenant_id is null or not exists(select 1 from public.profiles where id=p_actor_id and tenant_id=p_expected_tenant_id and status='active') then raise exception 'Active administrator and server-owned tenant binding required' using errcode='42501';end if;
 select * into p from public.legal_ai_policy_versions where id=p_policy_version_id and tenant_id=p_expected_tenant_id and model=p_model;if not found or p_account_id !~ '^[a-zA-Z0-9_-]{1,100}$' or p_enabled is null then raise exception 'Exact server account/model/policy binding required' using errcode='22023';end if;
 if exists(select 1 from public.legal_ai_connections where account_id=p_account_id and tenant_id<>p_expected_tenant_id) then raise exception 'AI account already belongs to a different tenant binding' using errcode='42501';end if;
 insert into public.legal_ai_connections(tenant_id,account_id,model,policy_version_id,enabled,state,created_by) values(p_expected_tenant_id,p_account_id,p_model,p.id,p_enabled,case when not p_enabled then 'disabled' when public._legal_assistance_policy_allowed(p.id,'general') then 'enabled' else 'policy_required' end,p_actor_id) on conflict(tenant_id) do update set account_id=excluded.account_id,model=excluded.model,policy_version_id=excluded.policy_version_id,enabled=excluded.enabled,state=excluded.state,updated_at=clock_timestamp() returning * into c;
 perform public._legal_assistance_event(c.tenant_id,null,'general','ai_connection_configured',jsonb_build_object('connection_id',c.id,'enabled',c.enabled),p_actor_id);return public._legal_assistance_projection(to_jsonb(c),'ai_connection');
end;$$;
create or replace function public._legal_assistance_ai_current(p_job public.legal_ai_jobs) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if not public._legal_assistance_actor(p_job.case_id,p_job.created_by,p_job.category,true) or (select id from public.legal_assistance_draft_versions where case_id=p_job.case_id and draft_key=p_job.draft_key order by version_number desc limit 1) is distinct from p_job.previous_version_id then return false;end if;
 return p_job.snapshot_hash=encode(sha256(convert_to(public._legal_assistance_snapshot(p_job.case_id,p_job.category,p_job.citation_ids,p_job.created_by)::text,'UTF8')),'hex');exception when insufficient_privilege or invalid_parameter_value then return false;
end;$$;
create or replace function public.legal_ai_enqueue(p_case_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public._legal_judicial_assert(p_case_id,p_payload->>'category');r public.legal_ai_jobs;c public.legal_ai_connections;snapshot jsonb;begin
 perform public._legal_judicial_payload(p_payload,array['draft_key','kind','category','purpose','citation_ids','max_output_tokens','idempotency_key']);perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||t,0));r.id:=gen_random_uuid();r.tenant_id:=t;r.case_id:=p_case_id;r.created_by:=auth.uid();r.created_at:=clock_timestamp();r.quota_month:=public._legal_assistance_month();r.consumption:='not_sent';r.reserved_cost:=0;r.quota_cost:=0;r:=jsonb_populate_record(r,p_payload);
 if length(btrim(coalesce(r.draft_key,''))) not between 1 and 80 or length(btrim(coalesce(r.purpose,''))) not between 1 and 2000 then raise exception 'Bounded drafting key and purpose required' using errcode='22023';end if;perform public._legal_assistance_validate_sources(p_case_id,r.category,r.citation_ids,auth.uid(),true);r.snapshot:=public._legal_assistance_snapshot(p_case_id,r.category,r.citation_ids,auth.uid());r.snapshot_hash:=encode(sha256(convert_to(r.snapshot::text,'UTF8')),'hex');r.payload_hash:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');
 if exists(select 1 from public.legal_ai_jobs old where old.tenant_id=t and old.idempotency_key=r.idempotency_key) then
  if not exists(select 1 from public.legal_ai_jobs old where old.tenant_id=t and old.idempotency_key=r.idempotency_key and old.payload_hash=r.payload_hash and old.case_id=p_case_id) then raise exception 'AI job idempotency payload mismatch' using errcode='22023';end if;select * into r from public.legal_ai_jobs old where old.tenant_id=t and old.idempotency_key=r.idempotency_key;return public._legal_assistance_projection(to_jsonb(r),'ai_job');
 end if;
 if exists(select 1 from public.legal_ai_jobs old where old.case_id=p_case_id and old.draft_key=r.draft_key and old.state in ('queued','running','not_configured')) then raise exception 'One live AI request per draft key; cancel before replacing it' using errcode='22023';end if;
 select * into c from public.legal_ai_connections where tenant_id=t;r.connection_id:=c.id;r.policy_version_id:=c.policy_version_id;r.state:=case when c.id is null or not c.enabled then 'not_configured' else 'queued' end;select id into r.previous_version_id from public.legal_assistance_draft_versions where case_id=p_case_id and draft_key=r.draft_key order by version_number desc limit 1;
 if exists(select 1 from public.legal_assistance_draft_versions old where old.id=r.previous_version_id and old.category<>r.category) then raise exception 'A draft series preserves its original category; create a separate series' using errcode='22023';end if;
 insert into public.legal_ai_jobs values(r.*) returning * into r;perform public._legal_assistance_event(t,p_case_id,r.category,'ai_requested',jsonb_build_object('job_id',r.id,'state',r.state));return public._legal_assistance_projection(to_jsonb(r),'ai_job');
end;$$;
create or replace function public.legal_ai_cancel(p_job_id uuid,p_note text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ai_jobs;begin
 select * into r from public.legal_ai_jobs where id=p_job_id;perform public._legal_judicial_assert(r.case_id,r.category);select * into r from public.legal_ai_jobs where id=p_job_id for update;if r.state not in ('queued','running','not_configured') or length(btrim(coalesce(p_note,''))) not between 1 and 2000 then raise exception 'Pending AI job and explicit cancellation reason required' using errcode='22023';end if;
 update public.legal_ai_jobs set state='cancelled',consumption=case when consumption='reserved' then 'uncertain' else consumption end,error_code='cancelled_by_staff',finished_at=clock_timestamp() where id=r.id returning * into r;perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'ai_cancelled',jsonb_build_object('job_id',r.id));return public._legal_assistance_projection(to_jsonb(r),'ai_job');
end;$$;
create or replace function public.legal_ai_service_claim(p_expected_tenant_id uuid,p_account_id text,p_model text,p_configured boolean) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ai_jobs;c public.legal_ai_connections;p public.legal_ai_policy_versions;citations jsonb;begin
 perform public._legal_portal_service();if p_expected_tenant_id is null or p_account_id is null or p_model is null then raise exception 'Explicit server binding required' using errcode='22023';end if;
 for r in select * from public.legal_ai_jobs where tenant_id=p_expected_tenant_id and state in ('queued','not_configured','running') order by created_at,id limit 50 loop
  perform 1 from public.legal_cases where id=r.case_id for update skip locked;if not found then continue;end if;select * into r from public.legal_ai_jobs where id=r.id for update skip locked;if not found then continue;end if;
  if r.state='running' then if r.lease_until<=clock_timestamp() then update public.legal_ai_jobs set state='unknown',consumption=case when consumption='reserved' then 'uncertain' else consumption end,error_code='lease_expired',lease_token=null,lease_until=null,finished_at=clock_timestamp() where id=r.id;end if;continue;end if;if r.state not in ('queued','not_configured') then continue;end if;
  select * into c from public.legal_ai_connections where tenant_id=p_expected_tenant_id and account_id=p_account_id and model=p_model for update;
  if not found or p_configured is distinct from true or not c.enabled then update public.legal_ai_jobs set state='not_configured',error_code='not_configured' where id=r.id;continue;end if;
  select * into p from public.legal_ai_policy_versions where id=c.policy_version_id;
  if not public._legal_assistance_policy_allowed(p.id,r.category) or r.max_output_tokens>p.max_output_tokens then update public.legal_ai_jobs set state='failed',error_code='policy_required' where id=r.id;continue;end if;
  if not public._legal_assistance_ai_current(r) then update public.legal_ai_jobs set state='authorization_revoked',error_code='source_or_permission_changed' where id=r.id;continue;end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',x->'id','quote',x->'quote','source_label',x->'source_label','page',x->'page_number')),'[]') into citations from jsonb_array_elements(public._legal_assistance_validate_sources(r.case_id,r.category,r.citation_ids,r.created_by,true)) x;
  update public.legal_ai_jobs set state='running',connection_id=c.id,policy_version_id=p.id,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '5 minutes',started_at=clock_timestamp(),error_code=null where id=r.id returning * into r;
  return jsonb_build_array(jsonb_build_object('id',r.id,'lease_token',r.lease_token,'input',jsonb_build_object('purpose',r.purpose,'kind',r.kind,'citations',citations,'max_output_tokens',r.max_output_tokens)));
 end loop;return '[]';
end;$$;
create or replace function public.legal_ai_service_authorize(p_job_id uuid,p_lease_token uuid,p_expected_tenant_id uuid,p_account_id text,p_model text,p_input_token_bound integer) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ai_jobs;c public.legal_ai_connections;p public.legal_ai_policy_versions;cost numeric;reason text;minimum integer;begin
 perform public._legal_portal_service();select * into r from public.legal_ai_jobs where id=p_job_id;perform 1 from public.legal_cases where id=r.case_id for update;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||r.tenant_id,0));perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||r.tenant_id,0));select * into r from public.legal_ai_jobs where id=p_job_id for update;select * into c from public.legal_ai_connections where id=r.connection_id for update;select * into p from public.legal_ai_policy_versions where id=r.policy_version_id;
 if p_lease_token is null or r.lease_token is distinct from p_lease_token or r.state<>'running' or r.consumption<>'not_sent' or r.tenant_id is distinct from p_expected_tenant_id or c.account_id is distinct from p_account_id or c.model is distinct from p_model then raise exception 'Unspent bound AI lease required' using errcode='42501';end if;
 minimum:=4096+octet_length(r.purpose)+(select coalesce(sum(octet_length(quote)+octet_length(source_label)+100),0) from public.legal_source_citations where id=any(r.citation_ids));
 if p_input_token_bound is null or p_input_token_bound<minimum or p_input_token_bound>least(50000,p.max_input_tokens) then raise exception 'Conservative complete-request token bound required' using errcode='22023';end if;
 if r.lease_until<=clock_timestamp() or not public._legal_assistance_ai_current(r) then reason:='source_or_permission_changed';elsif not c.enabled or c.policy_version_id<>r.policy_version_id or not public._legal_assistance_policy_allowed(p.id,r.category) then reason:='policy_or_connection_changed';end if;
 cost:=ceil((p_input_token_bound*p.input_rate+r.max_output_tokens*p.output_rate))/1000000;
 if reason is null and (select coalesce(sum(quota_cost),0) from public.legal_ai_jobs where tenant_id=r.tenant_id and quota_month=public._legal_assistance_month())+cost>p.monthly_budget then reason:='monthly_budget_exceeded';end if;
 if reason is not null then update public.legal_ai_jobs set state=case when reason='monthly_budget_exceeded' then 'quota_exhausted' else 'authorization_revoked' end,error_code=reason,lease_token=null,lease_until=null,finished_at=clock_timestamp() where id=r.id;return jsonb_build_object('allowed',false,'reason',reason);end if;
 update public.legal_ai_jobs set input_token_bound=p_input_token_bound,reserved_cost=cost,quota_cost=cost,quota_month=public._legal_assistance_month(),consumption='reserved' where id=r.id;
 perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'ai_consumption_reserved',jsonb_build_object('job_id',r.id),r.created_by);return jsonb_build_object('allowed',true,'reserved_cost',cost::numeric(18,6)::text);
end;$$;
create or replace function public.legal_ai_service_finish(p_job_id uuid,p_lease_token uuid,p_outcome jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r public.legal_ai_jobs;c public.legal_ai_connections;p public.legal_ai_policy_versions;v public.legal_assistance_draft_versions;measured numeric;input_n integer;output_n integer;authorized boolean;valid_body boolean:=false;failure text;begin
 perform public._legal_portal_service();select * into r from public.legal_ai_jobs where id=p_job_id;perform 1 from public.legal_cases where id=r.case_id for update;perform pg_advisory_xact_lock(hashtextextended('legal_assistance_catalog:'||r.tenant_id,0));perform pg_advisory_xact_lock(hashtextextended('legal_assistance_quota:'||r.tenant_id,0));select * into r from public.legal_ai_jobs where id=p_job_id for update;select * into c from public.legal_ai_connections where id=r.connection_id;select * into p from public.legal_ai_policy_versions where id=r.policy_version_id;
 if p_lease_token is null or r.lease_token is distinct from p_lease_token or r.state not in ('running','cancelled') or r.consumption not in ('not_sent','reserved','uncertain') then raise exception 'Current AI completion lease required' using errcode='42501';end if;
 if r.consumption='not_sent' and (p_outcome->'ok' is distinct from 'false'::jsonb or p_outcome->>'consumption' is distinct from 'not_sent' or p_outcome?'body' or p_outcome?'response_id' or (p_outcome?'usage' and p_outcome->'usage'<>'null'::jsonb)) then raise exception 'Unreserved lease may only report a pre-send failure without usage or content' using errcode='42501';end if;
 perform public._legal_judicial_payload(p_outcome,array['ok','body','usage','response_id','code','consumption']);if jsonb_typeof(p_outcome->'ok') is distinct from 'boolean' or octet_length(p_outcome::text)>100000 then raise exception 'Bounded AI outcome required' using errcode='22023';end if;
 if p_outcome->'ok'='true'::jsonb then
  if not(p_outcome ?& array['ok','body','usage','response_id']) or p_outcome?'code' or p_outcome?'consumption' or jsonb_typeof(p_outcome->'response_id') is distinct from 'string' or coalesce(p_outcome->>'response_id','') !~ '^resp_[a-zA-Z0-9_-]{1,195}$' then raise exception 'Successful provider outcome requires body, usage state and verified response reference' using errcode='22023';end if;
 else
  if not(p_outcome ?& array['ok','code','consumption']) or p_outcome?'body' or p_outcome?'response_id' or jsonb_typeof(p_outcome->'code') is distinct from 'string' or coalesce(p_outcome->>'code','') !~ '^[a-zA-Z0-9_:-]{1,100}$' or jsonb_typeof(p_outcome->'consumption') is distinct from 'string' or p_outcome->>'consumption' not in ('not_sent','reported','uncertain') then raise exception 'Failure outcome requires a normalized code and explicit consumption state, without generated content' using errcode='22023';end if;
  if (p_outcome->>'consumption'='reported') is distinct from (coalesce(p_outcome->'usage','null'::jsonb)<>'null'::jsonb) then raise exception 'Reported consumption and usage must agree' using errcode='22023';end if;
 end if;
 if p_outcome->'usage' is not null and p_outcome->'usage'<>'null'::jsonb then
  perform public._legal_judicial_payload(p_outcome->'usage',array['input_tokens','output_tokens']);if jsonb_typeof(p_outcome->'usage'->'input_tokens') is distinct from 'number' or jsonb_typeof(p_outcome->'usage'->'output_tokens') is distinct from 'number' or coalesce(p_outcome->'usage'->>'input_tokens','') !~ '^[0-9]{1,7}$' or coalesce(p_outcome->'usage'->>'output_tokens','') !~ '^[0-9]{1,7}$' then raise exception 'Reported usage must contain integer token counts' using errcode='22023';end if;
  input_n:=(p_outcome->'usage'->>'input_tokens')::integer;output_n:=(p_outcome->'usage'->>'output_tokens')::integer;if input_n>1000000 or output_n>1000000 then raise exception 'Reported token usage exceeds safety bound' using errcode='22023';end if;measured:=ceil(input_n*p.input_rate+output_n*p.output_rate)/1000000;
 end if;
 authorized:=r.state='running' and r.lease_until>clock_timestamp() and c.enabled and c.policy_version_id=r.policy_version_id and public._legal_assistance_policy_allowed(p.id,r.category) and public._legal_assistance_ai_current(r);
 if p_outcome->'ok'='true'::jsonb then
  if p_outcome->>'response_id' !~ '^resp_[a-zA-Z0-9_-]{1,195}$' then failure:='invalid_provider_reference';else begin perform public._legal_assistance_body(p_outcome->'body',r.citation_ids);valid_body:=true;exception when others then failure:='invalid_generated_body';end;end if;
 else if p_outcome->>'code' !~ '^[a-zA-Z0-9_:-]{1,100}$' or p_outcome->>'consumption' not in ('not_sent','uncertain','reported') then raise exception 'Normalized failure and consumption state required' using errcode='22023';end if;failure:=p_outcome->>'code';end if;
 if measured is not null and (input_n>r.input_token_bound or output_n>r.max_output_tokens) then failure:='usage_exceeded_reserved_bound';valid_body:=false;end if;
 if authorized and valid_body then
  v:=public._legal_assistance_insert_draft(r.case_id,jsonb_build_object('draft_key',r.draft_key,'kind',r.kind,'category',r.category,'purpose',r.purpose,'body',p_outcome->'body','citation_ids',r.citation_ids,'previous_version_id',r.previous_version_id),r.created_by,'ai',r.id);
 end if;
 update public.legal_ai_jobs set state=case when state='cancelled' then 'cancelled' when not authorized then 'authorization_revoked' when v.id is not null then 'succeeded' when measured is null and coalesce(p_outcome->>'consumption','uncertain')<>'not_sent' then 'unknown' else 'failed' end,consumption=case when measured is not null then 'reported' when p_outcome->'ok'='false'::jsonb and p_outcome->>'consumption'='not_sent' then 'not_sent' else 'uncertain' end,input_tokens=input_n,output_tokens=output_n,measured_cost=measured,quota_cost=case when measured is not null then measured when p_outcome->'ok'='false'::jsonb and p_outcome->>'consumption'='not_sent' then 0 else reserved_cost end,result_version_id=v.id,response_id=case when v.id is not null then p_outcome->>'response_id' else null end,error_code=case when not authorized then 'source_or_authorization_revoked' else failure end,lease_token=null,lease_until=null,finished_at=clock_timestamp() where id=r.id returning * into r;
 perform public._legal_assistance_event(r.tenant_id,r.case_id,r.category,'ai_finished',jsonb_build_object('job_id',r.id,'state',r.state,'consumption',r.consumption),r.created_by);return jsonb_build_object('job',public._legal_assistance_projection(to_jsonb(r),'ai_job'),'version_id',v.id);
end;$$;
create or replace function public.legal_assistance_context(p_case_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public.legal_actual_tenant();s public.legal_assistance_settings;c public.legal_ai_connections;p public.legal_ai_policy_versions;begin
 if not public.legal_can_access_case(p_case_id) then raise exception 'Assistance workspace access denied' using errcode='42501';end if;select * into s from public.legal_assistance_settings where tenant_id=t;select * into c from public.legal_ai_connections where tenant_id=t;select * into p from public.legal_ai_policy_versions where id=c.policy_version_id;if c.enabled and c.state<>'not_configured' and not public._legal_assistance_policy_allowed(p.id,'general') then c.state:='policy_required';end if;
 return jsonb_build_object('tenant_id',t,'user_id',auth.uid(),'can_edit',public.legal_can_access_case(p_case_id,true),'can_review',public.legal_can_access_case(p_case_id,true,true),'can_manage',public._legal_judicial_admin(),'settings',case when s.tenant_id is null then jsonb_build_object('tenant_id',t,'ocr_enabled',false,'ocr_monthly_page_limit',1000,'ocr_max_pages',20,'updated_by',null,'updated_at',null) else to_jsonb(s) end,
 'ocr_usage',jsonb_build_object('month',public._legal_assistance_month(),'charged_pages',(select coalesce(sum(quota_pages),0) from public.legal_ocr_jobs where tenant_id=t and quota_month=public._legal_assistance_month()),'monthly_limit',coalesce(s.ocr_monthly_page_limit,1000)),
 'ai_connection',case when c.id is null then null else public._legal_assistance_projection(to_jsonb(c),'ai_connection') end,'ai_usage',case when c.id is null then null else jsonb_build_object('month',public._legal_assistance_month(),'currency',p.currency,'quota_cost',(select coalesce(sum(quota_cost),0)::numeric(18,6)::text from public.legal_ai_jobs where tenant_id=t and quota_month=public._legal_assistance_month()),'monthly_budget',p.monthly_budget::text) end);
end;$$;
create or replace function public.legal_assistance_list(p_case_id uuid,p_kind text,p_limit integer default 25,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare t uuid:=public.legal_actual_tenant();r record;result jsonb:='[]';more boolean:=false;n integer:=0;begin
 if not public.legal_can_access_case(p_case_id) then raise exception 'Assistance case access denied' using errcode='42501';end if;if p_kind not in ('ocr_jobs','text_versions','knowledge','drafts','ai_jobs','ai_policies') or p_limit not between 1 and 50 or p_offset not between 0 and 100000 then raise exception 'Bounded assistance list required' using errcode='22023';end if;
 for r in
  with entries as (
   select public._legal_assistance_projection(to_jsonb(j),'ocr_job') body,j.created_at,j.id from public.legal_ocr_jobs j where p_kind='ocr_jobs' and j.case_id=p_case_id and public._legal_assistance_actor(j.case_id,auth.uid(),j.category)
   union all select public._legal_assistance_projection(to_jsonb(v),'text_version')||jsonb_build_object('is_current',public._legal_assistance_text_current(v.id,auth.uid())),v.created_at,v.id from public.legal_document_text_versions v where p_kind='text_versions' and v.case_id=p_case_id and public._legal_assistance_actor(v.case_id,auth.uid(),v.category)
   union all select public._legal_assistance_projection(to_jsonb(k),'knowledge')||jsonb_build_object('is_current',public._legal_assistance_knowledge_access(k.id,auth.uid(),true)),k.created_at,k.id from public.legal_knowledge_versions k where p_kind='knowledge' and k.tenant_id=t and (public._legal_assistance_knowledge_access(k.id,auth.uid()) or (k.state='revoked' and (k.source_document_id is null or exists(select 1 from public.legal_case_documents d where d.id=k.source_document_id and public._legal_assistance_actor(d.case_id,auth.uid(),'general')))))
   union all select public._legal_assistance_projection(to_jsonb(v),'draft')||jsonb_build_object('title',v.body->>'title','is_current',public._legal_assistance_draft_current(v.id,auth.uid())),v.created_at,v.id from public.legal_assistance_draft_versions v where p_kind='drafts' and v.case_id=p_case_id and public._legal_assistance_actor(v.case_id,auth.uid(),v.category)
   union all select public._legal_assistance_projection(to_jsonb(j),'ai_job'),j.created_at,j.id from public.legal_ai_jobs j where p_kind='ai_jobs' and j.case_id=p_case_id and public._legal_assistance_actor(j.case_id,auth.uid(),j.category)
   union all select public._legal_assistance_projection(to_jsonb(p),'ai_policy'),p.created_at,p.id from public.legal_ai_policy_versions p where p_kind='ai_policies' and p.tenant_id=t and (p.source_document_id is null or exists(select 1 from public.legal_case_documents d where d.id=p.source_document_id and public._legal_assistance_actor(d.case_id,auth.uid(),'general')))
  ) select * from entries order by created_at desc,id limit p_limit+1 offset p_offset
 loop if n>=p_limit then more:=true;exit;end if;result:=result||jsonb_build_array(r.body);n:=n+1;end loop;
 return jsonb_build_object('items',result,'has_more',more);
end;$$;
create or replace function public._legal_assistance_transfer_current(p_kind text,p_target uuid) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare tr public.legal_assistance_transfers;v public.legal_assistance_draft_versions;begin
 select * into tr from public.legal_assistance_transfers where target_kind=p_kind and target_id=p_target;if not found then return true;end if;select * into v from public.legal_assistance_draft_versions where id=tr.version_id;
 return v.state='reviewed' and public._legal_assistance_actor(v.case_id,v.reviewed_by,v.category,true,true) and public._legal_assistance_draft_current(v.id,v.reviewed_by);
end;$$;

create or replace function public._legal_assistance_review_instrument_base(p_version_id uuid,p_decision text,p_note text default '')
returns public.legal_instrument_versions language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare r public.legal_instrument_versions;
begin
 select * into r from public.legal_instrument_versions where id=p_version_id;
 if not found then raise exception 'Instrument access denied' using errcode='42501'; end if;
 perform 1 from public.legal_instruments where id=r.instrument_id for update;
 select * into r from public.legal_instrument_versions where id=p_version_id for update;
 perform public._legal_assert_operation(r.case_id,r.category,true);
 if p_decision not in ('approved','revoked') or r.status='revoked' or (p_decision='approved' and (r.status<>'in_review' or r.superseded_at is not null))
  or (p_decision='revoked' and length(btrim(coalesce(p_note,'')))=0) then raise exception 'Invalid instrument review transition' using errcode='22023'; end if;
 update public.legal_instrument_versions set status=p_decision,reviewer_id=auth.uid(),review_note=p_note,
  approved_at=case when p_decision='approved' then now() else approved_at end,revoked_at=case when p_decision='revoked' then now() else revoked_at end where id=r.id returning * into r;
 perform public._legal_record_event(r.case_id,'instrument_reviewed','Decisão de revisão registrada.',jsonb_build_object('version_id',r.id,'status',r.status));return r;
end;$$;

create or replace function public._legal_assistance_review_publication_base(p_publication_id uuid,p_decision text,p_note text) returns public.legal_portal_publications language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare r public.legal_portal_publications;m public.legal_portal_memberships;begin
 select * into r from public.legal_portal_publications where id=p_publication_id;perform public._legal_assert_operation(r.case_id,r.category,true);select * into r from public.legal_portal_publications where id=p_publication_id for update;
 if coalesce(p_decision,'') not in ('approved','revoked') or length(btrim(coalesce(p_note,''))) not between 1 and 4000 or (p_decision='approved' and r.state<>'draft') then raise exception 'Publication requires an immutable draft and review' using errcode='22023';end if;
 if p_decision='approved' then
  select * into m from public.legal_portal_memberships where id=r.membership_id;perform public._legal_portal_assert_member(m.identity_id,m.id,case when r.publication_kind='agenda' then 'agenda:read' else 'case_summary:read' end,r.category);
  if r.previous_version_id is not null then update public.legal_portal_publications set state='superseded' where id=r.previous_version_id;end if;
 end if;
 update public.legal_portal_publications set state=p_decision,reviewed_by=auth.uid(),reviewed_at=clock_timestamp(),review_note=p_note where id=r.id returning * into r;
 perform public._legal_portal_event(r.case_id,r.membership_id,auth.uid(),'publication_reviewed',jsonb_build_object('publication_id',r.id,'decision',p_decision));return r;
end;$$;

create or replace function public._legal_assistance_portal_case_base(p_actor_id uuid,p_membership_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare m public.legal_portal_memberships;begin
 perform public._legal_portal_service();select * into m from public.legal_portal_memberships where id=p_membership_id;m:=public._legal_portal_assert_member(p_actor_id,m.id,null,case when m.access_kind='accountant' then 'fiscal' else 'general' end);
 return jsonb_build_object('membership',public._legal_portal_member_projection(m),
 'publications',case when 'case_summary:read'=any(m.scopes) then coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'category',p.category,'publication_kind',p.publication_kind,'title',p.title,'body',p.body,'created_at',p.created_at,'reviewed_at',p.reviewed_at) order by p.reviewed_at,p.id) from public.legal_portal_publications p where p.membership_id=m.id and p.state='approved' and p.publication_kind<>'agenda' and public._legal_portal_category(m,p.category)),'[]') else '[]'::jsonb end,
 'agenda',case when 'agenda:read'=any(m.scopes) then coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'category',p.category,'title',p.title,'body',p.body,'starts_at',p.starts_at,'ends_at',p.ends_at,'reviewed_at',p.reviewed_at) order by p.starts_at,p.id) from public.legal_portal_publications p where p.membership_id=m.id and p.state='approved' and p.publication_kind='agenda' and public._legal_portal_category(m,p.category)),'[]') else '[]'::jsonb end,
 'documents',case when 'documents:read'=any(m.scopes) then coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'document_id',d.id,'category',r.category,'display_name',d.display_name,'file_name',d.file_name,'mime_type',d.mime_type,'size_bytes',d.size_bytes,'sha256',d.sha256,'purpose',r.purpose,'expires_at',r.expires_at) order by r.created_at,r.id) from public.legal_portal_document_releases r join public.legal_case_documents d on d.id=r.document_id where r.membership_id=m.id and r.state='approved' and r.expires_at>clock_timestamp() and d.status='ready' and d.sha256=r.document_hash and public._legal_portal_category(m,r.category)),'[]') else '[]'::jsonb end,
 'requests',case when 'requests:upload'=any(m.scopes) then public.legal_portal_service_requests(p_actor_id,m.id) else '[]'::jsonb end,
 'messages',case when 'messages:read'=any(m.scopes) then coalesce((select jsonb_agg(x.item order by x.created_at,x.id) from (
 select p.id,p.created_at,jsonb_build_object('id',p.id,'category',p.category,'body',p.body,'direction','client','created_at',p.created_at) item from public.legal_portal_messages p where p.membership_id=m.id and public._legal_portal_category(m,p.category)
 union all select c.id,c.created_at,jsonb_build_object('id',c.id,'category',c.category,'body',c.body,'direction','office','created_at',c.created_at) from public.legal_communication_versions c where c.membership_id=m.id and c.channel='portal' and c.state='approved' and c.expires_at>clock_timestamp() and public._legal_portal_category(m,c.category) and exists(select 1 from public.legal_communication_jobs j where j.communication_id=c.id and j.state in ('delivered','read'))) x),'[]') else '[]'::jsonb end,
 'exports',case when 'fiscal_exports:read'=any(m.scopes) and m.allow_fiscal then coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'title',e.title,'reviewed_at',e.reviewed_at) order by e.created_at,e.id) from public.legal_portal_export_versions e where e.membership_id=m.id and e.state='approved'),'[]') else '[]'::jsonb end);
end;$$;

create or replace function public._legal_assistance_portal_ack_base(p_actor_id uuid,p_publication_id uuid,p_membership_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare p public.legal_portal_publications;m public.legal_portal_memberships;r public.legal_portal_acknowledgements;begin
 perform public._legal_portal_service();select * into p from public.legal_portal_publications where id=p_publication_id and membership_id=p_membership_id;
 m:=public._legal_portal_assert_member(p_actor_id,p_membership_id,case when p.publication_kind='agenda' then 'agenda:read' else 'case_summary:read' end,p.category);select * into p from public.legal_portal_publications where id=p_publication_id and membership_id=m.id and state='approved';
 if not found then raise exception 'Published version unavailable' using errcode='42501';end if;
 insert into public.legal_portal_acknowledgements(tenant_id,case_id,membership_id,publication_id,identity_id) values(m.tenant_id,m.case_id,m.id,p.id,p_actor_id) on conflict(membership_id,publication_id) do nothing;
 select * into r from public.legal_portal_acknowledgements where membership_id=m.id and publication_id=p.id;
 return jsonb_build_object('id',r.id,'acknowledged_at',r.acknowledged_at);
end;$$;
create or replace function public.legal_review_instrument(p_version_id uuid,p_decision text,p_note text default '') returns public.legal_instrument_versions language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare v public.legal_instrument_versions;begin
 select * into v from public.legal_instrument_versions where id=p_version_id;if not found then raise exception 'Instrument access denied' using errcode='42501';end if;perform 1 from public.legal_instruments where id=v.instrument_id for update;select * into v from public.legal_instrument_versions where id=p_version_id for update;perform public._legal_assert_operation(v.case_id,v.category,true);
 if p_decision='approved' and v.version_number=1 and not public._legal_assistance_transfer_current('instrument',v.instrument_id) then raise exception 'Derived draft sources changed before instrument review' using errcode='42501';end if;return public._legal_assistance_review_instrument_base(p_version_id,p_decision,p_note);
end;$$;
create or replace function public.legal_review_portal_publication(p_publication_id uuid,p_decision text,p_note text) returns public.legal_portal_publications language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare p public.legal_portal_publications;begin
 select * into p from public.legal_portal_publications where id=p_publication_id;perform public._legal_assert_operation(p.case_id,p.category,true);
 if p_decision='approved' and not public._legal_assistance_transfer_current('publication',p.id) then raise exception 'Derived draft sources changed before individual publication review' using errcode='42501';end if;return public._legal_assistance_review_publication_base(p_publication_id,p_decision,p_note);
end;$$;
create or replace function public.legal_portal_service_case(p_actor_id uuid,p_membership_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;begin
 r:=public._legal_assistance_portal_case_base(p_actor_id,p_membership_id);
 return r||jsonb_build_object('publications',coalesce((select jsonb_agg(p) from jsonb_array_elements(coalesce(r->'publications','[]')) p where public._legal_assistance_transfer_current('publication',(p->>'id')::uuid)),'[]'));
end;$$;
create or replace function public.legal_portal_service_acknowledge(p_actor_id uuid,p_publication_id uuid,p_membership_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare p public.legal_portal_publications;begin
 perform public._legal_portal_service();select * into p from public.legal_portal_publications where id=p_publication_id;perform 1 from public.legal_cases where id=p.case_id for update;
 if not public._legal_assistance_transfer_current('publication',p.id) then raise exception 'Derived publication unavailable after source revocation' using errcode='42501';end if;return public._legal_assistance_portal_ack_base(p_actor_id,p_publication_id,p_membership_id);
end;$$;
do $$declare tab text;fn record;begin
 foreach tab in array array['legal_assistance_settings','legal_assistance_audit','legal_ocr_jobs','legal_document_text_versions','legal_document_text_pages','legal_document_text_reviews','legal_knowledge_versions','legal_source_citations','legal_assistance_draft_versions','legal_assistance_draft_reviews','legal_assistance_transfers','legal_ai_policy_versions','legal_ai_connections','legal_ai_jobs'] loop
  execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated,legal_portal,service_role',tab);execute format('grant select on public.%I to service_role',tab);
 end loop;
 for fn in select p.oid::regprocedure sig,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like '\_legal\_assistance\_%' escape '\' or p.proname like 'legal\_assistance\_%' escape '\' or p.proname like 'legal\_ocr\_%' escape '\' or p.proname like 'legal\_text\_%' escape '\' or p.proname like 'legal\_knowledge\_%' escape '\' or p.proname like 'legal\_ai\_%' escape '\') loop
  execute format('revoke all on function %s from public,anon,authenticated,legal_portal,service_role',fn.sig);
  if fn.proname not like '\_%' escape '\' then execute format('grant execute on function %s to %I',fn.sig,case when position('_service_' in fn.proname)>0 then 'service_role' else 'authenticated' end);end if;
 end loop;
end;$$;
-- Existing public delegates retain their original grants; private copies are revoked above.
notify pgrst,'reload schema';
